const fmtMoney = (n: number) =>
  new Intl.NumberFormat("ru-RU").format(n) + " ₽";

function DeltaBadge({ value }: { value: number | null }) {
  if (value === null) {
    return (
      <span className="text-[10px] text-slate-400 inline-flex items-center gap-0.5">
