      <span className="text-[10px] text-slate-400 inline-flex items-center gap-0.5">
        <Minus className="w-3 h-3" />0%
      </span>
    );
  }
  const isUp = value > 0;
  return (
    <span
      className={`text-[10px] font-semibold inline-flex items-center gap-0.5 ${
        isUp ? "text-emerald-600" : "text-rose-600"
      }`}
