import { useEffect, useMemo, useState } from "react";
import {
  Palmtree,
  Plus,
  Check,
  X,
  AlertCircle,
} from "lucide-react";

// ─── Константы ─────────────────────────────────────
const CELL_WIDTH = 34;
const ROW_HEIGHT = 56;
const EMP_COL_WIDTH = 200;
const DAYS_IN_MONTH = 31;
const TODAY_DAY = 15;

const WEEKDAYS = ["пн", "вт", "ср", "чт", "пт", "сб", "вс"];

const getWeekdayShort = (day: number): string => {
  const d = new Date(2026, 9, day);
  const dow = d.getDay();
  const idx = dow === 0 ? 6 : dow - 1;
  return WEEKDAYS[idx];
};

const isWeekend = (day: number): boolean => {
  const d = new Date(2026, 9, day);
  const dow = d.getDay();
  return dow === 0 || dow === 6;
};

// ─── Типы ──────────────────────────────────────────
type Employee = {
  id: string;
  name: string;
  position: string;
  color: string;
};

type Vacation = {
  id: string;
  employeeId: string;
  startDay: number;
  endDay: number;
  status: "approved" | "pending";
};

const EMPLOYEES: Employee[] = [
  { id: "e1", name: "Мария Иванова", position: "продавец", color: "#3b82f6" },
  { id: "e2", name: "Иван Петров", position: "повар", color: "#8b5cf6" },
  { id: "e3", name: "Анна Сидорова", position: "официант", color: "#10b981" },
  { id: "e4", name: "Олег Кузнецов", position: "бариста", color: "#f59e0b" },
];

const INITIAL_VACATIONS: Vacation[] = [
  { id: "v1", employeeId: "e1", startDay: 5, endDay: 10, status: "approved" },
  { id: "v2", employeeId: "e2", startDay: 15, endDay: 22, status: "approved" },
  { id: "v3", employeeId: "e3", startDay: 3, endDay: 7, status: "pending" },
  { id: "v4", employeeId: "e1", startDay: 20, endDay: 25, status: "approved" },
  { id: "v5", employeeId: "e4", startDay: 26, endDay: 29, status: "pending" },
];

let idCounter = 100;
const nextId = () => `v${idCounter++}`;

// ─── Проверка пересечения ──────────────────────────
const rangesOverlap = (a1: number, b1: number, a2: number, b2: number) =>
  a1 <= b2 && a2 <= b1;

const isFree = (
  vacations: Vacation[],
  employeeId: string,
  start: number,
  end: number,
  excludeId?: string
): boolean => {
  if (start > end) return false;
  for (const v of vacations) {
    if (v.employeeId !== employeeId) continue;
    if (excludeId && v.id === excludeId) continue;
    if (rangesOverlap(start, end, v.startDay, v.endDay)) return false;
  }
  return true;
};

// ─── Drag state ────────────────────────────────────
type DragMode = "move" | "resize-start" | "resize-end";

type DragState = {
  id: string;
  mode: DragMode;
  startX: number;
  origStart: number;
  origEnd: number;
  currentStart: number;
  currentEnd: number;
} | null;

// ─── Компонент ─────────────────────────────────────
type Props = {
  onInteract?: () => void;
};

export default function VacationsDemo({ onInteract }: Props) {
  const [vacations, setVacations] = useState<Vacation[]>(INITIAL_VACATIONS);
  const [drag, setDrag] = useState<DragState>(null);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({
    employeeId: EMPLOYEES[0].id,
    startDay: 10,
    endDay: 15,
  });
  const [formError, setFormError] = useState<string | null>(null);

  const interact = () => onInteract?.();

  const pending = useMemo(
    () => vacations.filter((v) => v.status === "pending"),
    [vacations]
  );

  const byEmployee = useMemo(() => {
    const map = new Map<string, Vacation[]>();
    for (const e of EMPLOYEES) map.set(e.id, []);
    for (const v of vacations) map.get(v.employeeId)?.push(v);
    return map;
  }, [vacations]);

  // Валидность формы (в реальном времени)
  const formValid =
    form.startDay >= 1 &&
    form.endDay <= DAYS_IN_MONTH &&
    form.startDay <= form.endDay &&
    isFree(vacations, form.employeeId, form.startDay, form.endDay);

  const formConflict =
    form.startDay <= form.endDay &&
    !isFree(vacations, form.employeeId, form.startDay, form.endDay);

  // ─── Drag ────────────────────────────────────────
  const onBarMouseDown = (
    e: React.MouseEvent,
    v: Vacation,
    mode: DragMode
  ) => {
    e.preventDefault();
    e.stopPropagation();
    setDrag({
      id: v.id,
      mode,
      startX: e.clientX,
      origStart: v.startDay,
      origEnd: v.endDay,
      currentStart: v.startDay,
      currentEnd: v.endDay,
    });
  };

  useEffect(() => {
    if (!drag) return;

    const draggedVac = vacations.find((v) => v.id === drag.id);
    if (!draggedVac) return;

    const onMove = (e: MouseEvent) => {
      const delta = Math.round((e.clientX - drag.startX) / CELL_WIDTH);
      let newStart = drag.origStart;
      let newEnd = drag.origEnd;

      if (drag.mode === "move") {
        newStart = drag.origStart + delta;
        newEnd = drag.origEnd + delta;
        const len = drag.origEnd - drag.origStart + 1;
        if (newStart < 1) {
          newStart = 1;
          newEnd = len;
        }
        if (newEnd > DAYS_IN_MONTH) {
          newEnd = DAYS_IN_MONTH;
          newStart = DAYS_IN_MONTH - len + 1;
        }
      } else if (drag.mode === "resize-start") {
        newStart = drag.origStart + delta;
        if (newStart < 1) newStart = 1;
        if (newStart > drag.currentEnd) newStart = drag.currentEnd;
      } else if (drag.mode === "resize-end") {
        newEnd = drag.origEnd + delta;
        if (newEnd > DAYS_IN_MONTH) newEnd = DAYS_IN_MONTH;
        if (newEnd < drag.currentStart) newEnd = drag.currentStart;
      }

      // 🛑 Главное: не пускаем в чужие отпуска
      if (
        !isFree(
          vacations,
          draggedVac.employeeId,
          newStart,
          newEnd,
          drag.id
        )
      ) {
        return; // замораживаем на последней валидной позиции
      }

      if (newStart !== drag.currentStart || newEnd !== drag.currentEnd) {
        setDrag((d) =>
          d ? { ...d, currentStart: newStart, currentEnd: newEnd } : d
        );
      }
    };

    const onUp = () => {
      if (
        drag.currentStart !== drag.origStart ||
        drag.currentEnd !== drag.origEnd
      ) {
        setVacations((prev) =>
          prev.map((v) =>
            v.id === drag.id
              ? { ...v, startDay: drag.currentStart, endDay: drag.currentEnd }
              : v
          )
        );
        interact();
      }
      setDrag(null);
    };

    document.addEventListener("mousemove", onMove);
    document.addEventListener("mouseup", onUp);
    return () => {
      document.removeEventListener("mousemove", onMove);
      document.removeEventListener("mouseup", onUp);
    };
  }, [drag, vacations]);

  // ─── CRUD ────────────────────────────────────────
  const addVacation = () => {
    if (!formValid) {
      setFormError("Диапазон пересекается с существующим отпуском сотрудника");
      return;
    }
    setVacations((prev) => [
      ...prev,
      {
        id: nextId(),
        employeeId: form.employeeId,
        startDay: form.startDay,
        endDay: form.endDay,
        status: "pending",
      },
    ]);
    setShowForm(false);
    setForm({
      employeeId: EMPLOYEES[0].id,
      startDay: 10,
      endDay: 15,
    });
    setFormError(null);
    interact();
  };

  const approve = (id: string) => {
    setVacations((prev) =>
      prev.map((v) => (v.id === id ? { ...v, status: "approved" } : v))
    );
    interact();
  };

  const reject = (id: string) => {
    setVacations((prev) => prev.filter((v) => v.id !== id));
    interact();
  };

  const remove = (id: string) => {
    setVacations((prev) => prev.filter((v) => v.id !== id));
    interact();
  };

  const resetAll = () => {
    setVacations(INITIAL_VACATIONS);
    setShowForm(false);
    setDrag(null);
    setFormError(null);
  };

  // ─── Рендер ──────────────────────────────────────
  return (
    <div className="bg-white rounded-xl">
      {/* Шапка */}
      <div className="flex items-center justify-between mb-4 flex-wrap gap-3">
        <div>
          <div className="text-base sm:text-lg font-semibold text-slate-900 flex items-center gap-2">
            <Palmtree className="w-5 h-5 text-emerald-600" />
            Отпуска · Октябрь 2026
          </div>
          <div className="text-sm text-slate-500 mt-1">
            {EMPLOYEES.length} сотрудников · {vacations.length} отпусков
            {pending.length > 0 && (
              <span className="ml-2 inline-flex items-center gap-1 text-amber-700">
                <AlertCircle className="w-3.5 h-3.5" />
                {pending.length} ждёт одобрения
              </span>
            )}
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={() => {
              setShowForm((v) => !v);
              setFormError(null);
            }}
            className="inline-flex items-center gap-2 px-4 py-2 bg-brand-600 text-white rounded-xl hover:bg-brand-700 text-sm font-medium transition-colors shadow-sm"
          >
            {showForm ? <X className="w-4 h-4" /> : <Plus className="w-4 h-4" />}
            {showForm ? "Отмена" : "Запросить отпуск"}
          </button>
        </div>
      </div>

      {/* Форма запроса */}
      {showForm && (
        <div className="mb-4 bg-slate-50 rounded-xl border border-slate-200 p-4 animate-fade-in">
          <div className="text-sm font-semibold text-slate-900 mb-3">
            Новый отпуск
          </div>
          <div className="grid sm:grid-cols-3 gap-3">
            <div>
              <label className="block text-xs font-medium text-slate-600 mb-1">
                Сотрудник
              </label>
              <select
                value={form.employeeId}
                onChange={(e) => {
                  setForm((f) => ({ ...f, employeeId: e.target.value }));
                  setFormError(null);
                }}
                className="!text-sm"
              >
                {EMPLOYEES.map((e) => (
                  <option key={e.id} value={e.id}>
                    {e.name}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-600 mb-1">
                С (число)
              </label>
              <input
                type="number"
                min={1}
                max={DAYS_IN_MONTH}
                value={form.startDay}
                onChange={(e) => {
                  setForm((f) => ({ ...f, startDay: Number(e.target.value) }));
                  setFormError(null);
                }}
                className={`!text-sm ${formConflict ? "!border-rose-400" : ""}`}
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-600 mb-1">
                По (число)
              </label>
              <input
                type="number"
                min={1}
                max={DAYS_IN_MONTH}
                value={form.endDay}
                onChange={(e) => {
                  setForm((f) => ({ ...f, endDay: Number(e.target.value) }));
                  setFormError(null);
                }}
                className={`!text-sm ${formConflict ? "!border-rose-400" : ""}`}
              />
            </div>
          </div>

          {/* Сообщение о пересечении */}
          {formConflict && (
            <div className="mt-3 bg-rose-50 border border-rose-200 rounded-lg px-3 py-2 text-xs text-rose-700 flex items-start gap-2">
              <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
              <span>
                У сотрудника уже есть отпуск в этом диапазоне. Выберите другие
                числа.
              </span>
            </div>
          )}
          {form.startDay > form.endDay && !formConflict && (
            <div className="mt-3 bg-rose-50 border border-rose-200 rounded-lg px-3 py-2 text-xs text-rose-700 flex items-start gap-2">
              <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
              <span>Дата начала позже даты окончания.</span>
            </div>
          )}

          <div className="mt-3 flex justify-end">
            <button
              onClick={addVacation}
              disabled={!formValid}
              className="inline-flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 disabled:opacity-50 disabled:cursor-not-allowed text-sm font-medium transition-colors"
              title={
                !formValid
                  ? "Диапазон невалиден или пересекается с существующим отпуском"
                  : ""
              }
            >
              <Check className="w-4 h-4" />
              Отправить на согласование
            </button>
          </div>
        </div>
      )}

      {/* Pending-заявки */}
      {pending.length > 0 && (
        <div className="mb-4 bg-amber-50 rounded-xl border border-amber-200 p-3 animate-fade-in">
          <div className="text-sm font-semibold text-amber-900 mb-2 flex items-center gap-2">
            <AlertCircle className="w-4 h-4" />
            Требуют одобрения ({pending.length})
          </div>
          <div className="space-y-2">
            {pending.map((v) => {
              const emp = EMPLOYEES.find((e) => e.id === v.employeeId)!;
              return (
                <div
                  key={v.id}
                  className="bg-white rounded-lg border border-amber-200 px-3 py-2 flex items-center gap-3 flex-wrap"
                >
                  <div
                    className="w-8 h-8 rounded-full flex items-center justify-center text-white text-xs font-bold shrink-0"
                    style={{ backgroundColor: emp.color }}
                  >
                    {emp.name.charAt(0)}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="text-sm font-medium text-slate-900">
                      {emp.name}{" "}
                      <span className="text-slate-500 font-normal">
                        · {v.startDay}–{v.endDay} октября
                      </span>
                    </div>
                    <div className="text-xs text-slate-500">Отпуск</div>
                  </div>
                  <div className="flex gap-1 shrink-0">
                    <button
                      onClick={() => approve(v.id)}
                      className="inline-flex items-center gap-1 px-2.5 py-1 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 text-xs font-medium"
                    >
                      <Check className="w-3 h-3" />
                      Одобрить
                    </button>
                    <button
                      onClick={() => reject(v.id)}
                      className="inline-flex items-center gap-1 px-2.5 py-1 text-rose-600 hover:bg-rose-50 rounded-lg text-xs font-medium"
                    >
                      <X className="w-3 h-3" />
                      Отклонить
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Легенда */}
      <div className="flex items-center gap-4 mb-3 text-xs text-slate-600 flex-wrap">
        <div className="flex items-center gap-1.5">
          <div className="w-3 h-3 rounded bg-emerald-500" />
          Одобрен
        </div>
        <div className="flex items-center gap-1.5">
          <div className="w-3 h-3 rounded bg-amber-400 ring-1 ring-amber-500" />
          На согласовании
        </div>
        <div className="flex items-center gap-1.5">
          <div className="w-3 h-3 rounded bg-blue-100 ring-1 ring-blue-300" />
          Сегодня
        </div>
        <div className="ml-auto text-slate-400 hidden sm:inline">
          💡 Тяните полосу · за края — растянуть (через другой отпуск не выйдет)
        </div>
      </div>

      {/* Гант */}
      <div className="-mx-1 overflow-x-auto pb-3">
        <div
          className="min-w-fit px-1"
          style={{ width: EMP_COL_WIDTH + DAYS_IN_MONTH * CELL_WIDTH }}
        >
          {/* Шапка дней */}
          <div className="flex border-b-2 border-slate-200 bg-slate-50 rounded-t-lg">
            <div
              className="shrink-0 px-3 py-2 text-xs font-bold uppercase tracking-wide text-slate-600 border-r-2 border-slate-200 flex items-center"
              style={{ width: EMP_COL_WIDTH }}
            >
              Сотрудник
            </div>
            {Array.from({ length: DAYS_IN_MONTH }, (_, i) => i + 1).map(
              (day) => {
                const weekend = isWeekend(day);
                const isToday = day === TODAY_DAY;
                return (
                  <div
                    key={day}
                    className={`shrink-0 flex flex-col items-center justify-center border-r border-slate-200 ${
                      isToday
                        ? "bg-blue-100"
                        : weekend
                        ? "bg-slate-100"
                        : "bg-slate-50"
                    }`}
                    style={{ width: CELL_WIDTH, height: 52 }}
                  >
                    <div
                      className={`text-[9px] uppercase tracking-wide ${
                        isToday
                          ? "text-blue-700 font-semibold"
                          : weekend
                          ? "text-slate-400"
                          : "text-slate-500"
                      }`}
                    >
                      {getWeekdayShort(day)}
                    </div>
                    <div
                      className={`text-xs font-bold ${
                        isToday
                          ? "text-blue-700"
                          : weekend
                          ? "text-slate-400"
                          : "text-slate-700"
                      }`}
                    >
                      {day}
                    </div>
                  </div>
                );
              }
            )}
          </div>

          {/* Строки */}
          {EMPLOYEES.map((emp) => {
            const empVacations = byEmployee.get(emp.id) ?? [];
            return (
              <div
                key={emp.id}
                className="flex border-b border-slate-100 hover:bg-slate-50/30 transition-colors"
                style={{ height: ROW_HEIGHT }}
              >
                <div
                  className="shrink-0 px-3 flex items-center gap-2 border-r-2 border-slate-200"
                  style={{ width: EMP_COL_WIDTH }}
                >
                  <div
                    className="w-8 h-8 rounded-full flex items-center justify-center text-white text-xs font-bold shrink-0"
                    style={{ backgroundColor: emp.color }}
                  >
                    {emp.name.charAt(0)}
                  </div>
                  <div className="min-w-0">
                    <div className="text-sm font-medium text-slate-900 truncate">
                      {emp.name}
                    </div>
                    <div className="text-[10px] text-slate-500 truncate">
                      {emp.position}
                    </div>
                  </div>
                </div>

                <div
                  className="relative"
                  style={{ width: DAYS_IN_MONTH * CELL_WIDTH }}
                >
                  {Array.from({ length: DAYS_IN_MONTH }, (_, i) => i + 1).map(
                    (day) => {
                      const weekend = isWeekend(day);
                      const isToday = day === TODAY_DAY;
                      return (
                        <div
                          key={day}
                          className={`absolute inset-y-0 border-r border-slate-100 ${
                            isToday
                              ? "bg-blue-50/60"
                              : weekend
                              ? "bg-slate-50"
                              : ""
                          }`}
                          style={{
                            left: (day - 1) * CELL_WIDTH,
                            width: CELL_WIDTH,
                          }}
                        />
                      );
                    }
                  )}

                  {empVacations.map((v) => {
                    const isDragging = drag?.id === v.id;
                    const startDay = isDragging
                      ? drag!.currentStart
                      : v.startDay;
                    const endDay = isDragging ? drag!.currentEnd : v.endDay;

                    const left = (startDay - 1) * CELL_WIDTH + 2;
                    const width = (endDay - startDay + 1) * CELL_WIDTH - 4;

                    const isPending = v.status === "pending";
                    const baseClass = isPending
                      ? "bg-amber-400 text-amber-900 ring-2 ring-amber-500"
                      : "bg-emerald-500 text-white";

                    return (
                      <div
                        key={v.id}
                        onMouseDown={(e) => onBarMouseDown(e, v, "move")}
                        className={`absolute rounded-md text-[11px] font-semibold flex items-center justify-center shadow-sm cursor-grab active:cursor-grabbing group transition-shadow ${baseClass} ${
                          isDragging
                            ? "shadow-lg opacity-90 ring-offset-1 ring-slate-900"
                            : "hover:ring-2 hover:ring-offset-1 hover:ring-slate-400"
                        }`}
                        style={{
                          left,
                          width,
                          top: 10,
                          height: ROW_HEIGHT - 20,
                        }}
                        title={`${v.startDay}–${v.endDay} октября`}
                      >
                        {width > 40 && (
                          <span className="truncate px-2 pointer-events-none">
                            {isPending ? "На согласовании" : "Отпуск"}
                          </span>
                        )}

                        <div
                          onMouseDown={(e) =>
                            onBarMouseDown(e, v, "resize-start")
                          }
                          className="absolute left-0 top-0 bottom-0 w-2 cursor-ew-resize hover:bg-white/30 rounded-l-md"
                        />
                        <div
                          onMouseDown={(e) =>
                            onBarMouseDown(e, v, "resize-end")
                          }
                          className="absolute right-0 top-0 bottom-0 w-2 cursor-ew-resize hover:bg-white/30 rounded-r-md"
                        />

                        {!isPending && !isDragging && width > 60 && (
                          <button
                            onMouseDown={(e) => e.stopPropagation()}
                            onClick={(e) => {
                              e.stopPropagation();
                              remove(v.id);
                            }}
                            className="absolute -top-1 -right-1 w-5 h-5 rounded-full bg-white border border-slate-300 shadow text-slate-500 hover:text-rose-600 hover:border-rose-300 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity z-10"
                            title="Удалить отпуск"
                          >
                            <X className="w-3 h-3" />
                          </button>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Подсказка + сброс */}
      <div className="mt-4 flex items-center justify-between gap-2 text-xs sm:text-sm text-slate-500 flex-wrap">
        <div className="flex items-center gap-1">
          <span className="hidden sm:inline">
            💡 Кликните на жёлтую полосу, чтобы одобрить сверху · тяните за
            края для изменения
          </span>
          <span className="sm:hidden">💡 Свайпните, чтобы увидеть весь месяц</span>
        </div>
        <button
          onClick={resetAll}
          className="text-xs font-medium text-slate-400 hover:text-brand-600 transition-colors"
        >
          Сбросить демо
        </button>
      </div>
    </div>
  );
}

frontend/src/components/landing/demos/We:
import { useMemo, useState } from "react";
import {
  Plus,
  X,
  GripVertical,
  Trash2,
  Check,
  Calendar,
  Copy,
  ClipboardPaste,
  ClipboardX,
} from "lucide-react";

// ─── Seed data ─────────────────────────────────────
type Employee = {
  id: string;
  name: string;
  position: string;
  color: string;
  rate: number; // Ставка в час
};

const EMPLOYEES: Employee[] = [
  { id: "e1", name: "Мария", position: "продавец", color: "#3b82f6", rate: 500 },
  { id: "e2", name: "Иван", position: "повар", color: "#8b5cf6", rate: 600 },
  { id: "e3", name: "Анна", position: "официант", color: "#10b981", rate: 450 },
  { id: "e4", name: "Олег", position: "бариста", color: "#f59e0b", rate: 400 },
];

const DATES = ["20", "21", "22", "23", "24", "25", "26"];
const WEEKDAYS = ["Пн", "Вт", "Ср", "Чт", "Пт", "Сб", "Вс"];

type DemoShift = {
  id: string;
  dayIndex: number;
  employeeId: string;
  startTime: string;
  endTime: string;
};

type ShiftTemplate = Omit<DemoShift, "id" | "dayIndex">;

type Clipboard =
  | { kind: "shift"; shift: ShiftTemplate }
  | { kind: "day"; shifts: ShiftTemplate[] }
  | null;

const INITIAL_SHIFTS: DemoShift[] = [
  { id: "s1", dayIndex: 0, employeeId: "e1", startTime: "09:00", endTime: "15:00" },
  { id: "s2", dayIndex: 0, employeeId: "e2", startTime: "12:00", endTime: "20:00" },
  { id: "s3", dayIndex: 1, employeeId: "e1", startTime: "09:00", endTime: "15:00" },
  { id: "s4", dayIndex: 2, employeeId: "e3", startTime: "14:00", endTime: "22:00" },
  { id: "s5", dayIndex: 3, employeeId: "e2", startTime: "12:00", endTime: "20:00" },
  { id: "s6", dayIndex: 4, employeeId: "e1", startTime: "10:00", endTime: "18:00" },
  { id: "s7", dayIndex: 4, employeeId: "e3", startTime: "14:00", endTime: "22:00" },
  { id: "s8", dayIndex: 5, employeeId: "e2", startTime: "10:00", endTime: "18:00" },
  { id: "s9", dayIndex: 5, employeeId: "e4", startTime: "08:00", endTime: "14:00" },
  { id: "s10", dayIndex: 6, employeeId: "e1", startTime: "12:00", endTime: "18:00" },
];

const calcHours = (start: string, end: string): number => {
  const [sh, sm] = start.split(":").map(Number);
  const [eh, em] = end.split(":").map(Number);
  let m = eh * 60 + em - (sh * 60 + sm);
  if (m <= 0) m += 24 * 60;
  return m / 60;
};

const calcCost = (start: string, end: string, rate: number) => {
  return Math.round(calcHours(start, end) * rate);
};

const fmtMoney = (n: number) => new Intl.NumberFormat("ru-RU").format(n) + " ₽";

let idCounter = 100;
const nextId = () => `s${idCounter++}`;

// ─── Компонент ─────────────────────────────────────
type Props = {
  onInteract?: () => void;
};

export default function WeekDemo({ onInteract }: Props) {
  const [shifts, setShifts] = useState<DemoShift[]>(INITIAL_SHIFTS);
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [dragOverDay, setDragOverDay] = useState<number | null>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [addingDay, setAddingDay] = useState<number | null>(null);
  const [clipboard, setClipboard] = useState<Clipboard>(null);

  const interact = () => onInteract?.();

  const stats = useMemo(() => {
    const totalShifts = shifts.length;
    const totalHours = shifts.reduce(
      (sum, s) => sum + calcHours(s.startTime, s.endTime),
      0
    );
    const totalCost = shifts.reduce((sum, s) => {
      const emp = EMPLOYEES.find((e) => e.id === s.employeeId);
      return sum + (emp ? calcCost(s.startTime, s.endTime, emp.rate) : 0);
    }, 0);
    return { shifts: totalShifts, hours: Math.round(totalHours), cost: totalCost };
  }, [shifts]);

  const byDay = useMemo(() => {
    const map = new Map<number, DemoShift[]>();
    for (let i = 0; i < 7; i++) map.set(i, []);
    for (const s of shifts) map.get(s.dayIndex)?.push(s);
    return map;
  }, [shifts]);

  // ─── Drag & Drop ─────────────────────────────────
  const onDragStart = (e: React.DragEvent, id: string) => {
    setDraggingId(id);
    e.dataTransfer.effectAllowed = "move";
    e.dataTransfer.setData("text/plain", id);
  };

  const onDragOver = (e: React.DragEvent, day: number) => {
    if (!draggingId) return;
    e.preventDefault();
    setDragOverDay(day);
  };

  const onDrop = (e: React.DragEvent, day: number) => {
    e.preventDefault();
    setDragOverDay(null);
    if (!draggingId) return;
    const shift = shifts.find((s) => s.id === draggingId);
    if (!shift || shift.dayIndex === day) {
      setDraggingId(null);
      return;
    }
    setShifts((prev) =>
      prev.map((s) => (s.id === draggingId ? { ...s, dayIndex: day } : s))
    );
    setDraggingId(null);
    interact();
  };

  const onDragEnd = () => {
    setDraggingId(null);
    setDragOverDay(null);
  };

  // ─── CRUD ────────────────────────────────────────
  const addShift = (
    dayIndex: number,
    employeeId: string,
    startTime: string,
    endTime: string
  ) => {
    setShifts((prev) => [
      ...prev,
      { id: nextId(), dayIndex, employeeId, startTime, endTime },
    ]);
    setAddingDay(null);
    interact();
  };

  const updateShift = (id: string, patch: Partial<DemoShift>) => {
    setShifts((prev) => prev.map((s) => (s.id === id ? { ...s, ...patch } : s)));
    setEditingId(null);
    interact();
  };

  const deleteShift = (id: string) => {
    setShifts((prev) => prev.filter((s) => s.id !== id));
    if (editingId === id) setEditingId(null);
    interact();
  };

  // ─── Копирование / Вставка ───────────────────────
  const copyShift = (shift: DemoShift) => {
    const { id, dayIndex, ...rest } = shift;
    setClipboard({ kind: "shift", shift: rest });
    interact();
  };

  const copyDay = (dayIndex: number) => {
    const dayShifts = byDay.get(dayIndex) ?? [];
    if (dayShifts.length === 0) return;
    setClipboard({
      kind: "day",
      shifts: dayShifts.map(({ id, dayIndex, ...rest }) => rest),
    });
    interact();
  };

  const pasteShift = (dayIndex: number) => {
    if (!clipboard || clipboard.kind !== "shift") return;
    setShifts((prev) => [
      ...prev,
      { id: nextId(), dayIndex, ...clipboard.shift },
    ]);
    interact();
  };

  const pasteDay = (dayIndex: number) => {
    if (!clipboard || clipboard.kind !== "day") return;
    const newShifts = clipboard.shifts.map((s) => ({
      id: nextId(),
      dayIndex,
      ...s,
    }));
    setShifts((prev) => [...prev, ...newShifts]);
    interact();
  };

  const clearClipboard = () => setClipboard(null);

  const resetAll = () => {
    setShifts(INITIAL_SHIFTS);
    setEditingId(null);
    setAddingDay(null);
    setClipboard(null);
  };

  const clipboardLabel =
    clipboard?.kind === "shift"
      ? "1 смена"
      : clipboard?.kind === "day"
      ? `${clipboard.shifts.length} смен (день)`
      : null;

  return (
    <div className="bg-white rounded-xl">
      {/* Шапка */}
      <div className="flex items-start justify-between mb-4 flex-wrap gap-3">
        <div>
          <div className="text-base sm:text-lg font-semibold text-slate-900 flex items-center gap-2">
            <Calendar className="w-5 h-5 text-brand-600" />
            Неделя 20–26 октября
          </div>
          <div className="text-sm text-slate-500 mt-1">
            {stats.shifts} смен · {stats.hours} ч
          </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="text-right hidden sm:block">
            <div className="text-[10px] uppercase tracking-wide text-slate-400 font-semibold mb-0.5">
              Бюджет
            </div>
            <div className="text-base font-bold text-emerald-600 leading-none">
              {fmtMoney(stats.cost)}
            </div>
          </div>

          {clipboardLabel && (
            <div className="inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-lg bg-amber-50 text-amber-800 ring-1 ring-amber-200 font-medium">
              <ClipboardPaste className="w-3.5 h-3.5" />
              <span className="hidden md:inline">В буфере: {clipboardLabel}</span>
              <span className="md:hidden">В буфере</span>
              <button
                onClick={clearClipboard}
                className="ml-1 text-amber-700 hover:text-amber-900 hover:bg-amber-100 rounded p-0.5 transition-colors"
                title="Очистить буфер"
              >
                <ClipboardX className="w-3.5 h-3.5" />
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Сетка */}
      <div className="-mx-1 overflow-x-auto pb-3">
        <div className="flex sm:grid sm:grid-cols-7 gap-2 sm:gap-3 px-1 w-max sm:w-auto sm:min-w-0 snap-x snap-mandatory">
          {DATES.map((date, i) => {
            const dayShifts = byDay.get(i) ?? [];
            const isOver = dragOverDay === i;
            const isWeekend = i >= 5;
            const canPaste = clipboard !== null;
            const hasShifts = dayShifts.length > 0;

            const dayCost = dayShifts.reduce((acc, s) => {
              const emp = EMPLOYEES.find((e) => e.id === s.employeeId);
              return acc + (emp ? calcCost(s.startTime, s.endTime, emp.rate) : 0);
            }, 0);

            return (
              <div
                key={i}
                onDragOver={(e) => onDragOver(e, i)}
                onDragLeave={() => setDragOverDay(null)}
                onDrop={(e) => onDrop(e, i)}
                className={`w-[calc(50vw_-_1rem)] min-w-[140px] sm:min-w-0 sm:w-auto shrink-0 snap-start rounded-xl border-2 min-h-[340px] p-2.5 flex flex-col transition-all ${
                  isOver
                    ? "border-brand-400 bg-brand-50 ring-4 ring-brand-300/30"
                    : isWeekend
                    ? "border-slate-200 bg-slate-50/60"
                    : "border-slate-200 bg-white"
                }`}
              >
                {/* Шапка дня (только дата и кнопки) */}
                <div className="mb-2.5 pb-2 border-b border-slate-200">
                  <div className="flex items-center justify-between mb-2">
                    <div className="text-xs sm:text-sm font-bold uppercase tracking-wide text-slate-500">
                      {WEEKDAYS[i]}
                    </div>
                    <div
                      className={`text-lg sm:text-xl font-bold ${
                        isWeekend ? "text-violet-600" : "text-slate-900"
                      }`}
                    >
                      {date}
                    </div>
                  </div>

                  <div className="flex items-center gap-0.5 justify-end">
                    <button
                      type="button"
                      onClick={() => copyDay(i)}
                      disabled={!hasShifts}
                      className="p-1 text-slate-400 hover:text-brand-600 hover:bg-brand-50 disabled:opacity-30 disabled:hover:bg-transparent disabled:hover:text-slate-400 rounded transition-colors"
                      title="Копировать все смены дня"
                    >
                      <Copy className="w-3.5 h-3.5" />
                    </button>
                    <button
                      type="button"
                      onClick={() => {
                        if (clipboard?.kind === "shift") pasteShift(i);
                        else if (clipboard?.kind === "day") pasteDay(i);
                      }}
                      disabled={!canPaste}
                      className="p-1 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 disabled:opacity-30 disabled:hover:bg-transparent disabled:hover:text-slate-400 rounded transition-colors"
                      title={
                        clipboard?.kind === "shift"
                          ? "Вставить смену"
                          : clipboard?.kind === "day"
                          ? "Вставить все смены дня"
                          : "Вставить"
                      }
                    >
                      <ClipboardPaste className="w-3.5 h-3.5" />
                    </button>
                  </div>
                </div>

                {/* Смены */}
                <div className="space-y-2 flex-1 min-w-0">
                  {dayShifts.map((s) => {
                    const emp = EMPLOYEES.find((e) => e.id === s.employeeId)!;
                    const isEditing = editingId === s.id;
                    const isDragging = draggingId === s.id;
                    const shiftCost = calcCost(s.startTime, s.endTime, emp.rate);

                    return (
                      <div
                        key={s.id}
                        draggable={!isEditing}
                        onDragStart={(e) => onDragStart(e, s.id)}
                        onDragEnd={onDragEnd}
                        onClick={() => !isEditing && setEditingId(s.id)}
                        className={`group relative text-xs sm:text-sm rounded-lg p-2 border-l-4 transition-all ${
                          isEditing
                            ? "ring-2 ring-brand-400 bg-white shadow-md z-10"
                            : "cursor-pointer hover:ring-2 hover:ring-slate-300 hover:shadow-sm pr-14"
                        } ${isDragging ? "opacity-30" : ""}`}
                        style={{
                          backgroundColor: emp.color + "15",
                          borderLeftColor: emp.color,
                        }}
                      >
                        {isEditing ? (
                          <ShiftEditor
                            shift={s}
                            onChange={(patch) => updateShift(s.id, patch)}
                            onDelete={() => deleteShift(s.id)}
                            onCancel={() => setEditingId(null)}
                            onCopy={() => {
                              copyShift(s);
                              setEditingId(null);
                            }}
                          />
                        ) : (
                          <>
                            <div className="flex items-center justify-between gap-1 mb-1 min-w-0">
                              <span className="text-[10px] sm:text-[11px] font-semibold text-slate-800 truncate">
                                {s.startTime}–{s.endTime}
                              </span>
                              <GripVertical className="w-3 h-3 text-slate-400 shrink-0 opacity-0 group-hover:opacity-100 transition-opacity -mt-0.5" />
                            </div>
                            
                            <div className="text-slate-700 font-medium text-[11px] sm:text-xs truncate">
                              {emp.name}
                            </div>
                            
                            {/* Должность */}
                            <div className="text-slate-500 text-[9px] sm:text-[10px] truncate mt-0.5">
                              {emp.position}
                            </div>

                            {/* Стоимость (ниже должности) */}
                            <div className="text-slate-800 font-bold text-[10px] sm:text-[11px] mt-1 truncate">
                              {shiftCost} ₽
                            </div>

                            <div className="absolute top-1 right-1 flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
                              <button
                                type="button"
                                onClick={(e) => {
                                  e.stopPropagation();
                                  copyShift(s);
                                }}
                                className="p-1 bg-white/90 backdrop-blur-sm rounded text-slate-500 hover:text-brand-600 hover:bg-white transition-colors shadow-sm"
                                title="Копировать смену"
                              >
                                <Copy className="w-3 h-3" />
                              </button>
                              <button
                                type="button"
                                onClick={(e) => {
                                  e.stopPropagation();
                                  deleteShift(s.id);
                                }}
                                className="p-1 bg-white/90 backdrop-blur-sm rounded text-slate-500 hover:text-rose-600 hover:bg-rose-50 transition-colors shadow-sm"
                                title="Удалить смену"
                              >
                                <Trash2 className="w-3 h-3" />
                              </button>
                            </div>
                          </>
                        )}
                      </div>
                    );
                  })}

                  {dayShifts.length === 0 && !addingDay && (
                    <div className="flex-1 flex items-center justify-center text-sm text-slate-300 select-none py-4">
                      —
                    </div>
                  )}
                </div>

                {/* Статистика дня (ВНИЗУ) */}
                <div className="flex items-center justify-between text-[10px] sm:text-xs text-slate-500 mt-2 pt-2 border-t border-slate-100">
                  <span>{dayShifts.length} см.</span>
                  <span className="font-semibold text-slate-700">
                    {dayCost > 0 ? fmtMoney(dayCost) : "—"}
                  </span>
                </div>

                {/* Добавление */}
                {addingDay === i ? (
                  <AddShiftForm
                    onCancel={() => setAddingDay(null)}
                    onSubmit={(empId, start, end) => addShift(i, empId, start, end)}
                  />
                ) : (
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      setAddingDay(i);
                    }}
                    className="mt-2 w-full text-xs text-slate-400 hover:text-brand-600 hover:bg-brand-50 py-2 rounded-lg transition-colors flex items-center justify-center gap-1 border border-dashed border-slate-200 hover:border-brand-300"
                  >
                    <Plus className="w-3.5 h-3.5" />
                    смена
                  </button>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Подсказка + сброс */}
      <div className="mt-4 flex items-center justify-between gap-2 text-xs sm:text-sm text-slate-500 flex-wrap">
        <div className="flex items-center gap-1">
          <span className="hidden sm:inline">
            💡 Перетащите · кликните для редактирования · наведите — копировать
            или удалить
          </span>
          <span className="sm:hidden">💡 Свайпните, чтобы увидеть всю неделю</span>
        </div>
        <button
          onClick={resetAll}
          className="text-xs font-medium text-slate-400 hover:text-brand-600 transition-colors"
        >
          Сбросить демо
        </button>
      </div>
    </div>
  );
}

// ─── Встроенный редактор смены ─────────────────────
function ShiftEditor({
  shift,
  onChange,
  onDelete,
  onCancel,
  onCopy,
}: {
  shift: DemoShift;
  onChange: (patch: Partial<DemoShift>) => void;
  onDelete: () => void;
  onCancel: () => void;
  onCopy: () => void;
}) {
  const [start, setStart] = useState(shift.startTime);
  const [end, setEnd] = useState(shift.endTime);

  return (
    <div className="space-y-1.5 min-w-0" onClick={(e) => e.stopPropagation()}>
      <div className="grid grid-cols-2 gap-1 min-w-0">
        <input
          type="text"
          inputMode="numeric"
          maxLength={5}
          value={start}
          onChange={(e) => setStart(e.target.value.replace(/[^\d:]/g, "").slice(0, 5))}
          onBlur={() => setStart(normalizeTime(start))}
          className="!text-[10px] !px-0.5 !py-0.5 !w-full !min-w-0 !text-center !tracking-tight"
          aria-label="Начало"
        />
        <input
          type="text"
          inputMode="numeric"
          maxLength={5}
          value={end}
          onChange={(e) => setEnd(e.target.value.replace(/[^\d:]/g, "").slice(0, 5))}
          onBlur={() => setEnd(normalizeTime(end, "18:00"))}
          className="!text-[10px] !px-0.5 !py-0.5 !w-full !min-w-0 !text-center !tracking-tight"
          aria-label="Конец"
        />
      </div>
      <div className="flex gap-1">
        <button
          onClick={() => onChange({ startTime: start, endTime: end })}
          className="flex-1 bg-brand-600 text-white py-1 rounded text-[11px] font-medium hover:bg-brand-700 flex items-center justify-center gap-0.5"
        >
          <Check className="w-3 h-3" />
          Готово
        </button>
        <button
          onClick={onCopy}
          className="px-1 py-1 text-slate-500 hover:bg-slate-100 rounded"
          title="Копировать"
        >
          <Copy className="w-3 h-3" />
        </button>
        <button
          onClick={onDelete}
          className="px-1 py-1 text-rose-600 hover:bg-rose-50 rounded"
          title="Удалить"
        >
          <Trash2 className="w-3 h-3" />
        </button>
        <button
          onClick={onCancel}
          className="px-1 py-1 text-slate-400 hover:bg-slate-100 rounded"
          title="Отмена"
        >
          <X className="w-3 h-3" />
        </button>
      </div>
    </div>
  );
}

// ─── Форма добавления ─────────────────────────────
function AddShiftForm({
  onCancel,
  onSubmit,
}: {
  onCancel: () => void;
  onSubmit: (empId: string, start: string, end: string) => void;
}) {
  const [empId, setEmpId] = useState(EMPLOYEES[0].id);
  const [start, setStart] = useState("09:00");
  const [end, setEnd] = useState("15:00");

  return (
    <div
      className="mt-2 space-y-1.5 min-w-0"
      onClick={(e) => e.stopPropagation()}
    >
      <select
        value={empId}
        onChange={(e) => setEmpId(e.target.value)}
        className="!text-[11px] !px-1 !py-1 !w-full !min-w-0"
      >
        {EMPLOYEES.map((e) => (
          <option key={e.id} value={e.id}>
            {e.name}
          </option>
        ))}
      </select>

      <div className="grid grid-cols-2 gap-1 min-w-0">
        <input
          type="text"
          inputMode="numeric"
          maxLength={5}
          value={start}
          onChange={(e) => setStart(e.target.value.replace(/[^\d:]/g, "").slice(0, 5))}
          onBlur={() => setStart(normalizeTime(start))}
          className="!text-[10px] !px-0.5 !py-1 !w-full !min-w-0 !text-center !tracking-tight"
          aria-label="Начало"
        />
        <input
          type="text"
          inputMode="numeric"
          maxLength={5}
          value={end}
          onChange={(e) => setEnd(e.target.value.replace(/[^\d:]/g, "").slice(0, 5))}
          onBlur={() => setEnd(normalizeTime(end, "18:00"))}
          className="!text-[10px] !px-0.5 !py-1 !w-full !min-w-0 !text-center !tracking-tight"
          aria-label="Конец"
        />
      </div>

      <div className="flex gap-1">
        <button
          onClick={() => onSubmit(empId, start, end)}
          className="flex-1 bg-brand-600 text-white py-1 rounded text-[11px] font-medium hover:bg-brand-700"
        >
          Добавить
        </button>
        <button
          onClick={onCancel}
          className="px-1 py-1 text-slate-500 hover:bg-slate-100 rounded"
        >
          <X className="w-3 h-3" />
        </button>
      </div>
    </div>
  );
}

// Хелпер нормализации времени
function normalizeTime(val: string, fallback = "09:00"): string {
  const digits = val.replace(/\D/g, "");
  if (digits.length === 0) return fallback;

  let h: number;
  let m: number;
  if (digits.length <= 2) {
    h = parseInt(digits, 10);
    m = 0;
  } else {
    h = parseInt(digits.slice(0, 2), 10);
    m = parseInt(digits.slice(2, 4).padEnd(2, "0"), 10);
  }
  if (isNaN(h)) h = 9;
  if (isNaN(m)) m = 0;
  h = Math.max(0, Math.min(23, h));
  m = Math.max(0, Math.min(59, m));
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
}

