            Опубликован
          </span>
        </div>

        {/* Сетка */}
        <div className="grid grid-cols-7 gap-1 p-2">
          {weekdays.map((d, i) => (
            <div key={d} className="text-center text-[10px] font-semibold text-slate-500 uppercase py-1">
              {d}
            </div>
          ))}
          {dates.map((day, i) => {
            const dayShifts = shifts[i] ?? [];
            return (
