  { value: "#84CC16", label: "Лаймовый" },
];

/** Hex-цвет + alpha для фона (0–100%). */
export function withAlpha(hex: string, percent: number): string {
  const p = Math.max(0, Math.min(100, percent));
  const a = Math.round((p / 100) * 255)
    .toString(16)
    .padStart(2, "0");
  return `${hex}${a}`;
}

