import { useEffect, useMemo, useState } from "react";
import {
  Play, Square, Activity, CalendarDays, Clock, ArrowRightLeft, ChevronLeft, ChevronRight,
  Check, X, Inbox, Send, XCircle, Palmtree, Plus, AlertCircle,
  Pencil, Bell, CalendarX2, Stethoscope, Undo2
} from "lucide-react";
import { meApi, type MyShift, type Colleague } from "../api/me";
import type { Vacation } from "../api/vacations";
import { timeOffApi } from "../api/timeOff";
import { shiftChangeRequestsApi, type ShiftChangeRequest } from "../api/shiftChangeRequests";
import { useTimeEntries } from "../store/timeEntries";
import { useSwaps } from "../store/swaps";
import { useVacations } from "../store/vacations";
import { useSickLeaves } from "../store/sickLeaves";
import { useAuth } from "../store/auth";
import { useNotifications } from "../store/notifications";
import { useOrganization } from "../store/organization";
import { alertDialog, confirmDialog } from "../store/dialogs";
import NavBar from "../components/NavBar";
import VacationsGantt from "../components/VacationsGantt";
import { weekDates, dayLabel, shortDate } from "../lib/dates";
import { validateShiftTimes } from "../lib/time";

type Tab = "schedule" | "vacations" | "sick";

const MONTHS_RU = ["Январь", "Февраль", "Март", "Апрель", "Май", "Июнь", "Июль", "Август", "Сентябрь", "Октябрь", "Ноябрь", "Декабрь"];

function formatDateTime(iso: string | null): string {
  if (!iso) return "—";
  const d = new Date(iso);
  const day = String(d.getDate()).padStart(2, "0");
  const month = String(d.getMonth() + 1).padStart(2, "0");
  const hh = String(d.getHours()).padStart(2, "0");
  const mm = String(d.getMinutes()).padStart(2, "0");
  return `${day}.${month} ${hh}:${mm}`;
}

function formatShortDate(iso: string): string {
  const d = new Date(iso + "T00:00:00Z");
  const months = ["янв", "фев", "мар", "апр", "май", "июн", "июл", "авг", "сен", "окт", "ноя", "дек"];
  return `${d.getUTCDate()} ${months[d.getUTCMonth()]}`;
}

function elapsedSince(iso: string): string {
  const ms = Date.now() - new Date(iso).getTime();
  const sec = Math.floor(ms / 1000);
  if (sec < 60) return `${sec} сек`;
  const totalMin = Math.floor(ms / 60000);
  const h = Math.floor(totalMin / 60);
  const m = totalMin % 60;
  if (h === 0) return `${m} мин`;
  return `${h} ч ${m} мин`;
}

export default function MySchedulePage() {
  const { user } = useAuth();
  const org = useOrganization((s) => s.org);
  const isTrial = org?.trialEndsAt && new Date(org.trialEndsAt) > new Date();
  const isPaid = org?.tariffExpiresAt && new Date(org.tariffExpiresAt) > new Date();
  const effectiveTariff = isTrial ? "pro" : (isPaid ? org?.tariffId : "free");
  const isFree = effectiveTariff === "free";
  const timeTrackingOn = org?.timeTrackingEnabled === true;

  const [tab, setTab] = useState<Tab>("schedule");
  const [shifts, setShifts] = useState<MyShift[]>([]);
  const [colleagues, setColleagues] = useState<Colleague[]>([]);
  const [loading, setLoading] = useState(true);
  const [filterYear, setFilterYear] = useState<string>(new Date().getFullYear().toString());
  const [filterMonthOnly, setFilterMonthOnly] = useState<string>(String(new Date().getMonth() + 1).padStart(2, "0"));
  const [showCompleted, setShowCompleted] = useState<boolean>(false);
  const [incomingShiftRequests, setIncomingShiftRequests] = useState<ShiftChangeRequest[]>([]);
  const [outgoingShiftRequests, setOutgoingShiftRequests] = useState<ShiftChangeRequest[]>([]);
  const [myTimeOffs, setMyTimeOffs] = useState<any[]>([]);
  const [dismissedOffers, setDismissedOffers] = useState<Set<string>>(new Set());

  const { active, fetchActive, clockIn, clockOut } = useTimeEntries();
  const { incoming, outgoing, available, create: createSwap, accept, decline, cancel, fetchMine, fetchAvailable } = useSwaps();
  const { mine: myVacations, fetchMine: fetchVacations, create: createVacation, update: updateVacation, remove: removeVacation } = useVacations();
  const { mine: mySickLeaves, fetchMine: fetchMineSickLeaves } = useSickLeaves();

  const [busy, setBusy] = useState(false);
  const [swapShift, setSwapShift] = useState<MyShift | null>(null);
  const [swapTarget, setSwapTarget] = useState<string>("");
  const [swapBusy, setSwapBusy] = useState(false);

  const [editShift, setEditShift] = useState<MyShift | null>(null);
  const [editForm, setEditForm] = useState({ shiftDate: "", startTime: "", endTime: "" });
  const [editBusy, setEditBusy] = useState(false);

  const [showVacForm, setShowVacForm] = useState(false);
  const [editingVacation, setEditingVacation] = useState<Vacation | null>(null);
  const [vacForm, setVacForm] = useState({ startDate: "", endDate: "", comment: "" });
  const [vacBusy, setVacBusy] = useState(false);

  const loadAll = async () => {
    try {
      const [s, cols, inReqs, outReqs, myTos] = await Promise.all([
        meApi.myShifts(),
        meApi.colleagues(),
        shiftChangeRequestsApi.incoming().catch(() => []),
        shiftChangeRequestsApi.outgoing().catch(() => []),
        timeOffApi.listMine().catch(() => []),
        fetchActive(),
        fetchMine(),
        fetchAvailable(),
        fetchVacations(),
        fetchMineSickLeaves(),
      ]);
      setShifts(s);
      setColleagues(cols);
      setIncomingShiftRequests(inReqs);
      setOutgoingShiftRequests(outReqs);
      setMyTimeOffs(myTos);
    } catch {
      await alertDialog("Ошибка загрузки", { variant: "error" });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadAll();
  }, []);

  const onClockIn = async () => {
    setBusy(true);
    try { await clockIn(); } 
    catch (e: any) { await alertDialog(e.response?.data?.error ?? "Ошибка", { variant: "error" }); } 
    finally { setBusy(false); }
  };

  const onClockOut = async () => {
    setBusy(true);
    try { await clockOut(); } 
    catch (e: any) { await alertDialog(e.response?.data?.error ?? "Ошибка", { variant: "error" }); } 
    finally { setBusy(false); }
  };

  const openSwapModal = (shift: MyShift) => {
    setSwapShift(shift);
    setSwapTarget("");
  };

  const closeSwapModal = () => {
    setSwapShift(null);
    setSwapTarget("");
  };

  const onConfirmSwap = async () => {
    if (!swapShift) return;
    setSwapBusy(true);
    try {
      await createSwap({ shiftId: swapShift.id, swapWithUserId: swapTarget || undefined });
      useNotifications.getState().refresh();
      closeSwapModal();
      await alertDialog("Запрос на обмен отправлен", { title: "Готово", variant: "success" });
      loadAll();
    } catch (e: any) {
      await alertDialog(e.response?.data?.error ?? "Ошибка", { variant: "error" });
    } finally {
      setSwapBusy(false);
    }
  };

  const onRequestTimeOff = async (shift: MyShift) => {
    const ok = await confirmDialog(`Запросить отгул на ${shift.shiftDate}?`, {
      title: "Отгул", confirmLabel: "Запросить", variant: "default",
    });
    if (!ok) return;
    try {
      await timeOffApi.create({ shiftId: shift.id, date: shift.shiftDate });
      await alertDialog("Запрос на отгул отправлен руководителю", { variant: "success" });
      loadAll();
    } catch (e: any) {
      await alertDialog(e.response?.data?.error ?? "Ошибка", { variant: "error" });
    }
  };

  const onCancelTimeOff = async (id: string) => {
    const ok = await confirmDialog("Отменить запрос на отгул?", { variant: "danger" });
    if (!ok) return;
    try {
      await timeOffApi.cancel(id);
      await alertDialog("Запрос на отгул отменен", { variant: "success" });
      loadAll();
    } catch (e: any) {
      await alertDialog(e.response?.data?.error ?? "Ошибка", { variant: "error" });
    }
  };

  const onAccept = async (id: string) => {
    try {
      await accept(id);
      useNotifications.getState().refresh();
      await loadAll();
      await alertDialog("Обмен принят — смена перешла к вам", { title: "Готово", variant: "success" });
    } catch (e: any) {
      await alertDialog(e.response?.data?.error ?? "Ошибка", { variant: "error" });
    }
  };

  const onDecline = async (id: string) => {
    try {
      await decline(id);
      // Для открытых обменов сервер удаляет только напоминание — прячем локально
      setDismissedOffers((prev) => {
        const n = new Set(prev);
        n.add(id);
        return n;
      });
      useNotifications.getState().refresh();
      await loadAll();
    } catch (e: any) {
      await alertDialog(e.response?.data?.error ?? "Ошибка", { variant: "error" });
    }
  };

  const onCancelSwap = async (id: string) => {
    try {
      await cancel(id);
      useNotifications.getState().refresh();
      await loadAll();
    } catch (e: any) {
      await alertDialog(e.response?.data?.error ?? "Ошибка", { variant: "error" });
    }
  };

  const openEditShift = (s: MyShift) => {
    setEditShift(s);
    setEditForm({ shiftDate: String(s.shiftDate).slice(0, 10), startTime: s.startTime, endTime: s.endTime });
  };

  const closeEditShift = () => {
    setEditShift(null);
    setEditForm({ shiftDate: "", startTime: "", endTime: "" });
  };

  const onSubmitEditShift = async () => {
    if (!editShift) return;
    const timeCheck = validateShiftTimes(editForm.startTime, editForm.endTime);
    if (!timeCheck.ok) {
      await alertDialog(timeCheck.message ?? "Неверное время смены", { title: "Ошибка в времени", variant: "error" });
      return;
    }
    setEditBusy(true);
    try {
      const { shiftsApi } = await import("../api/weeks");
      const result = await shiftsApi.update(editShift.id, {
        shiftDate: editForm.shiftDate,
        startTime: editForm.startTime,
        endTime: editForm.endTime,
      });
      if (result.kind === "requested") {
        await alertDialog("Изменение отправлено на согласование руководителю", { title: "Готово", variant: "success" });
      } else {
        await alertDialog("Смена обновлена", { title: "Готово", variant: "success" });
      }
      closeEditShift();
      await loadAll();
    } catch (e: any) {
      await alertDialog(e.response?.data?.error ?? e.message ?? "Ошибка", { variant: "error" });
    } finally {
      setEditBusy(false);
    }
  };

  const onApproveShiftChange = async (id: string) => {
    try {
      await shiftChangeRequestsApi.approve(id);
      useNotifications.getState().refresh();
      await loadAll();
    } catch (e: any) {
      await alertDialog(e.message ?? "Ошибка", { variant: "error" });
    }
  };

  const onRejectShiftChange = async (id: string) => {
    try {
      await shiftChangeRequestsApi.reject(id);
      useNotifications.getState().refresh();
      await loadAll();
    } catch (e: any) {
      await alertDialog(e.message ?? "Ошибка", { variant: "error" });
    }
  };

  const openCreateForm = () => { setEditingVacation(null); setVacForm({ startDate: "", endDate: "", comment: "" }); setShowVacForm(true); };
  const openEditForm = (v: Vacation) => { setEditingVacation(v); setVacForm({ startDate: v.startDate, endDate: v.endDate, comment: v.comment ?? "" }); setShowVacForm(true); };
  const closeVacForm = () => { setEditingVacation(null); setVacForm({ startDate: "", endDate: "", comment: "" }); setShowVacForm(false); };

  const onSaveVacation = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!vacForm.startDate || !vacForm.endDate) return alertDialog("Заполните даты", { variant: "error" });
    if (vacForm.startDate > vacForm.endDate) return alertDialog("Дата начала позже окончания", { variant: "error" });
    
    setVacBusy(true);
    try {
      if (editingVacation) {
        await updateVacation(editingVacation.id, { startDate: vacForm.startDate, endDate: vacForm.endDate, comment: vacForm.comment || null });
      } else {
        await createVacation({ startDate: vacForm.startDate, endDate: vacForm.endDate, comment: vacForm.comment || undefined });
      }
      useNotifications.getState().refresh();
      closeVacForm();
      await alertDialog(editingVacation ? "Изменения отправлены на согласование руководителю" : "Отпуск отправлен на согласование руководителю", { title: "Готово", variant: "success" });
    } catch (err: any) {
      await alertDialog(err.response?.data?.error ?? "Ошибка", { variant: "error" });
    } finally {
      setVacBusy(false);
    }
  };

  const onDeleteVacation = async (id: string) => {
    try { await removeVacation(id); useNotifications.getState().refresh(); } 
    catch (err: any) { await alertDialog(err.response?.data?.error ?? "Ошибка", { variant: "error" }); }
  };

  const onGanttUpdate = async (id: string, payload: { startDate: string; endDate: string }) => {
    try {
      await updateVacation(id, { startDate: payload.startDate, endDate: payload.endDate });
      useNotifications.getState().refresh();
      await alertDialog("Изменения отправлены на согласование руководителю", { title: "Готово", variant: "success" });
    } catch (err: any) {
      await alertDialog(err.response?.data?.error ?? "Ошибка сохранения", { variant: "error" });
    }
  };

  const toGanttVacation = (s: any): Vacation => ({
    id: s.id,
    orgId: "",
    userId: s.userId,
    startDate: s.startDate,
    endDate: s.endDate,
    comment: s.comment,
    status: "APPROVED",
    previousStartDate: null,
    previousEndDate: null,
    previousComment: null,
    reviewedBy: null,
    reviewedAt: null,
    createdAt: s.createdAt ?? new Date().toISOString(),
    userName: s.userName,
  });

  const incomingActive = incoming.filter((r) => r.status === "PENDING");
  const outgoingActive = outgoing.filter((r) => r.status === "PENDING");

  type VirtualShift = { id: string; date: string; startTime: string; endTime: string; templateId: string | null; kind: "CREATE" | "SWAP"; fromName: string; requestId: string; };
  const virtualShifts: VirtualShift[] = [];

  for (const r of incomingShiftRequests) {
    if (r.status === "PENDING" && r.kind === "CREATE") {
      virtualShifts.push({ id: `create-${r.id}`, date: String(r.newShiftDate).slice(0, 10), startTime: r.newStartTime, endTime: r.newEndTime, templateId: r.templateId ?? null, kind: "CREATE", fromName: r.requestedByName ?? "—", requestId: r.id });
    }
  }
      // Оранжевые обмены убраны, так как они уже есть в фиолетовых (dayOffers)

  function weekStartOf(dateStr: string): string {
    const d = new Date(dateStr + "T00:00:00Z");
    const dow = d.getUTCDay();
    const diff = dow === 0 ? -6 : 1 - dow;
    d.setUTCDate(d.getUTCDate() + diff);
    return d.toISOString().slice(0, 10);
  }

  const groups = new Map<string, MyShift[]>();
  for (const s of shifts) {
    if (s.weekStatus === "DRAFT") continue;
    const dateStr = String(s.shiftDate).slice(0, 10);
    const ws = weekStartOf(dateStr);
    if (!groups.has(ws)) groups.set(ws, []);
    groups.get(ws)!.push(s);
  }

  const virtualGroups = new Map<string, VirtualShift[]>();
  for (const v of virtualShifts) {
    const ws = weekStartOf(v.date);
    if (!virtualGroups.has(ws)) virtualGroups.set(ws, []);
    virtualGroups.get(ws)!.push(v);
  }

  const allWeekKeys = new Set<string>([...groups.keys(), ...virtualGroups.keys()]);
  for (const a of available) {
    if (dismissedOffers.has(a.id)) continue;
    if (!a.shiftDate) continue;
    allWeekKeys.add(weekStartOf(String(a.shiftDate).slice(0, 10)));
  }
  const todayStr = new Date().toISOString().slice(0, 10);
  const uniqueYears = Array.from(new Set([
    ...Array.from(allWeekKeys).map(ws => ws.slice(0, 4)),
    new Date().getFullYear().toString()
  ])).sort();

  const sortedWeeks = Array.from(allWeekKeys).sort().filter(ws => {
    const endD = new Date(ws + "T00:00:00Z");
    endD.setUTCDate(endD.getUTCDate() + 6);
    const weekEndStr = endD.toISOString().slice(0, 10);
    const isPast = weekEndStr < todayStr;

    if (!showCompleted && isPast) return false;

    const startYear = ws.slice(0, 4);
    const endYear = weekEndStr.slice(0, 4);
    const startMonth = ws.slice(5, 7);
    const endMonth = weekEndStr.slice(5, 7);

    // Фильтр по году
    if (filterYear) {
      if (startYear !== filterYear && endYear !== filterYear) return false;
    }

    // Фильтр по месяцу
    if (filterMonthOnly) {
      if (startMonth !== filterMonthOnly && endMonth !== filterMonthOnly) return false;
    }

    return true;
  });

  const availableByDate = useMemo(() => {
    const map = new Map<string, typeof available>();
    const seenShiftIds = new Set<string>();

    for (const a of available) {
      if (dismissedOffers.has(a.id)) continue;
      if (!a.shiftDate) continue;
      if (a.status !== "PENDING") continue;
      
      if (seenShiftIds.has(a.shiftId)) continue;

      const d = String(a.shiftDate).slice(0, 10);
      if (!map.has(d)) map.set(d, []);
      map.get(d)!.push(a);
      seenShiftIds.add(a.shiftId);
    }
    return map;
  }, [available, dismissedOffers]);

  const pendingIncomingByShift = useMemo(() => {
    const m = new Map<string, ShiftChangeRequest>();
    for (const r of incomingShiftRequests) if (r.status === "PENDING" && r.shiftId) m.set(r.shiftId, r);
    return m;
  }, [incomingShiftRequests]);

  const pendingOutgoingByShift = useMemo(() => {
    const m = new Map<string, ShiftChangeRequest>();
    for (const r of outgoingShiftRequests) if (r.status === "PENDING" && r.shiftId) m.set(r.shiftId, r);
    return m;
  }, [outgoingShiftRequests]);

  const otherColleagues = colleagues.filter((c) => c.id !== user?.id);
  const today = new Intl.DateTimeFormat('en-CA').format(new Date());
  const upcomingVacations = myVacations.filter((v) => v.endDate >= today);

  const tabs: { id: Tab; label: string; icon: React.ElementType; badge?: number }[] = [
    { id: "schedule", label: "Расписание", icon: CalendarDays, badge: incomingActive.length + incomingShiftRequests.length + myTimeOffs.filter(t => t.status === "PENDING").length > 0 ? incomingActive.length + incomingShiftRequests.length + myTimeOffs.filter(t => t.status === "PENDING").length : undefined },
    { id: "vacations", label: "Отпуска", icon: Palmtree, badge: upcomingVacations.length > 0 ? upcomingVacations.length : undefined },
    { id: "sick", label: "Больничные", icon: Stethoscope, badge: mySickLeaves.length > 0 ? mySickLeaves.length : undefined },
  ];

  const handlePrevYear = () => {
    setFilterYear((parseInt(filterYear) - 1).toString());
  };
  const handleNextYear = () => {
    setFilterYear((parseInt(filterYear) + 1).toString());
  };
  const handlePrevMonth = () => {
    let m = parseInt(filterMonthOnly) - 1;
    if (m < 1) m = 12;
    setFilterMonthOnly(String(m).padStart(2, "0"));
  };
  const handleNextMonth = () => {
    let m = parseInt(filterMonthOnly) + 1;
    if (m > 12) m = 1;
    setFilterMonthOnly(String(m).padStart(2, "0"));
  };

  return (
    <div className="min-h-screen bg-slate-50">
      <NavBar />
      <main className="max-w-7xl mx-auto px-4 sm:px-6 py-8">
        <div className="flex items-start justify-between gap-4 mb-6 flex-wrap">
          <div>
            <h1 className="text-3xl font-bold text-slate-900">Мой график</h1>
            <p className="text-sm text-slate-500 mt-1">Ваши смены, отпуска, обмены и учёт рабочего времени</p>
          </div>
          {timeTrackingOn && (
            <div>
              {!active ? (
                <button onClick={onClockIn} disabled={busy} className="inline-flex items-center gap-2 bg-emerald-600 text-white px-4 py-2.5 rounded-xl hover:bg-emerald-700 disabled:opacity-50 text-sm font-medium shadow-sm hover:shadow transition-all">
                  <Play className="w-4 h-4" /> {busy ? "..." : "Начать смену"}
                </button>
              ) : (
                <button onClick={onClockOut} disabled={busy} className="inline-flex items-center gap-2 bg-red-600 text-white px-4 py-2.5 rounded-xl hover:bg-red-700 disabled:opacity-50 text-sm font-medium shadow-sm hover:shadow transition-all">
                  <Square className="w-4 h-4" /> {busy ? "..." : "Закончить смену"}
                </button>
              )}
            </div>
          )}
        </div>

        {timeTrackingOn && active && (
          <div className="bg-emerald-50 border border-emerald-200 rounded-2xl p-4 mb-6 flex items-start gap-3 animate-fade-in">
            <div className="w-10 h-10 rounded-xl bg-emerald-100 flex items-center justify-center shrink-0"><Activity className="w-5 h-5 text-emerald-600" /></div>
            <div className="flex-1 min-w-0">
              <div className="font-semibold text-emerald-900">Смена открыта</div>
              <div className="text-sm text-emerald-700 mt-0.5">Начало: {formatDateTime(active.clockIn)} · Прошло {elapsedSince(active.clockIn!)}</div>
            </div>
          </div>
        )}

        <div className="flex gap-2 mb-6 overflow-x-auto pb-1">
          {tabs.map((t) => {
            const Icon = t.icon;
            const isActive = tab === t.id;
            return (
              <button key={t.id} onClick={() => setTab(t.id)} className={`relative inline-flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-medium whitespace-nowrap transition-all ${isActive ? "bg-brand-600 text-white shadow-sm" : "bg-white text-slate-600 border border-slate-200 hover:bg-slate-50"}`}>
                <Icon className="w-4 h-4" /> {t.label}
                {t.badge !== undefined && <span className={`text-xs px-1.5 py-0.5 rounded-md font-semibold ${isActive ? "bg-white/20 text-white" : "bg-slate-100 text-slate-600"}`}>{t.badge > 99 ? "99+" : t.badge}</span>}
              </button>
            );
          })}
        </div>

        {tab === "schedule" && (
          <>
            {incomingShiftRequests.length > 0 && (
              <div className="bg-white rounded-2xl border border-amber-200 shadow-sm p-5 mb-6 animate-fade-in">
                <h3 className="font-semibold text-slate-900 mb-3 flex items-center gap-2"><Bell className="w-4 h-4 text-amber-600" /> Изменения смен — требуется ваше согласие <span className="text-xs px-2 py-0.5 rounded-full bg-amber-50 text-amber-700 font-medium ring-1 ring-amber-200">{incomingShiftRequests.length}</span></h3>
                <div className="space-y-2">
                  {incomingShiftRequests.map((r) => (
                    <div key={r.id} className="border-l-4 border-amber-500 bg-amber-50/40 pl-3 pr-2 py-3 rounded-r-lg">
                      <div className="text-sm text-slate-900 mb-1">
                        {r.kind === "CREATE" ? <span className="font-medium">Новая смена: {r.newShiftDate.slice(0, 10)} · {r.newStartTime}–{r.newEndTime}</span> : <><span className="text-slate-400 line-through mr-2">{r.oldShiftDate.slice(0, 10)} {r.oldStartTime}–{r.oldEndTime}</span><span className="font-medium">{r.newShiftDate.slice(0, 10)} {r.newStartTime}–{r.newEndTime}</span></>}
                      </div>
                      <div className="text-xs text-slate-500 mb-2">Инициатор: {r.requestedByName ?? "—"}</div>
                      <div className="flex gap-2">
                        <button onClick={() => onApproveShiftChange(r.id)} className="inline-flex items-center gap-1.5 bg-emerald-600 text-white px-3 py-1.5 rounded-lg hover:bg-emerald-700 text-xs font-medium transition-colors"><Check className="w-3.5 h-3.5" /> Принять</button>
                        <button onClick={() => onRejectShiftChange(r.id)} className="inline-flex items-center gap-1.5 text-red-600 hover:bg-red-50 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors"><X className="w-3.5 h-3.5" /> Отклонить</button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {incomingActive.length > 0 && (
              <div className="bg-white rounded-2xl border border-orange-200 shadow-sm p-5 mb-6 animate-fade-in">
                <h3 className="font-semibold text-slate-900 mb-3 flex items-center gap-2"><Inbox className="w-4 h-4 text-amber-600" /> Входящие предложения обмена <span className="text-xs px-2 py-0.5 rounded-full bg-orange-50 text-orange-700 font-medium ring-1 ring-orange-200">{incomingActive.length}</span></h3>
                <div className="space-y-2">
                  {incomingActive.map((r) => (
                    <div key={r.id} className="flex items-center justify-between gap-3 border-l-4 border-orange-500 bg-orange-50/40 pl-3 pr-2 py-3 rounded-r-lg flex-wrap">
                      <div className="min-w-0">
                        <div className="font-medium text-slate-900 text-sm">Обмен сменой</div>
                        <div className="text-xs text-slate-500 mt-0.5">{r.shiftDate ? <><span className="font-medium text-slate-700">{shortDate(String(r.shiftDate).slice(0, 10))}</span>{" · "}{r.startTime}–{r.endTime}</> : "—"}{r.requestedByName && ` · от ${r.requestedByName}`}</div>
                      </div>
                      <div className="flex items-center gap-1 shrink-0">
                        <button onClick={() => onAccept(r.id)} className="inline-flex items-center gap-1.5 bg-emerald-600 text-white px-3 py-1.5 rounded-lg hover:bg-emerald-700 text-xs font-medium transition-colors"><Check className="w-3.5 h-3.5" /> Принять</button>
                        <button onClick={() => onDecline(r.id)} className="inline-flex items-center gap-1.5 text-slate-500 hover:text-red-600 hover:bg-red-50 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors"><X className="w-3.5 h-3.5" /> Отклонить</button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {outgoingActive.length > 0 && (
              <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-5 mb-6">
                <h3 className="font-semibold text-slate-900 mb-3 flex items-center gap-2"><Send className="w-4 h-4 text-slate-400" /> Мои предложения <span className="text-xs px-2 py-0.5 rounded-full bg-slate-100 text-slate-600 font-medium">{outgoingActive.length}</span></h3>
                <div className="space-y-2">
                  {outgoingActive.map((r) => {
                    const target = r.swapWithUserId ? colleagues.find((c) => c.id === r.swapWithUserId)?.name ?? "—" : "Открытая (любой)";
                    return (
                      <div key={r.id} className="flex items-center justify-between gap-3 border-l-4 border-slate-300 bg-slate-50 pl-3 pr-2 py-2.5 rounded-r-lg flex-wrap">
                        <div className="text-sm min-w-0"><div className="text-slate-700">Ожидает ответа: <span className="font-medium">{target}</span></div></div>
                        <button onClick={() => onCancelSwap(r.id)} className="inline-flex items-center gap-1.5 text-slate-500 hover:text-red-600 hover:bg-red-50 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors"><XCircle className="w-3.5 h-3.5" /> Отменить</button>
                      </div>
                    );
                  })}
                </div>
              </div>
            )}

            {loading && <p className="text-slate-500 text-sm">Загрузка...</p>}

            {!loading && shifts.length === 0 && available.length === 0 && (
              <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-12 text-center">
                <div className="w-16 h-16 rounded-2xl bg-slate-100 flex items-center justify-center mx-auto mb-4"><CalendarDays className="w-8 h-8 text-slate-400" /></div>
                <h3 className="font-semibold text-slate-900 mb-1">У вас пока нет смен</h3>
                <p className="text-sm text-slate-500 max-w-sm mx-auto">Когда руководитель назначит вам смены и опубликует график, они появятся здесь</p>
              </div>
            )}

            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 mb-4 bg-white p-4 rounded-2xl border border-slate-200 shadow-sm animate-fade-in">
              <div className="flex items-center gap-4 flex-wrap">
                <div className="flex items-center gap-3 flex-wrap">
                  {/* Блок года */}
                  <div className="flex items-center gap-1 bg-white border border-slate-200 rounded-lg p-1 shadow-sm">
                    <button
                      onClick={handlePrevYear}
                      className="p-1 hover:bg-slate-100 rounded text-slate-600 transition-colors"
                    >
                      <ChevronLeft className="w-4 h-4" />
                    </button>
                    <div className="flex items-center px-1 text-sm font-semibold text-slate-900 min-w-[60px] justify-center">
                      <select
                        value={filterYear}
                        onChange={(e) => setFilterYear(e.target.value)}
                        className="!w-auto !p-0 !border-0 !bg-transparent focus:!ring-0 cursor-pointer text-center"
                      >
                        {Array.from(new Set([...uniqueYears, filterYear])).sort().map(y => (
                          <option key={y} value={y}>{y}</option>
                        ))}
                      </select>
                    </div>
                    <button
                      onClick={handleNextYear}
                      className="p-1 hover:bg-slate-100 rounded text-slate-600 transition-colors"
                    >
                      <ChevronRight className="w-4 h-4" />
                    </button>
                  </div>

                  {/* Блок месяца */}
                  <div className="flex items-center gap-1 bg-white border border-slate-200 rounded-lg p-1 shadow-sm">
                    <button
                      onClick={handlePrevMonth}
                      className="p-1 hover:bg-slate-100 rounded text-slate-600 transition-colors"
                    >
                      <ChevronLeft className="w-4 h-4" />
                    </button>
                    <div className="flex items-center px-1 text-sm font-semibold text-slate-900 min-w-[100px] justify-center">
                      <select
                        value={filterMonthOnly}
                        onChange={(e) => setFilterMonthOnly(e.target.value)}
                        className="!w-auto !p-0 !border-0 !bg-transparent focus:!ring-0 cursor-pointer text-center"
                      >
                        {MONTHS_RU.map((m, i) => (
                          <option key={i} value={String(i + 1).padStart(2, "0")}>{m}</option>
                        ))}
                      </select>
                    </div>
                    <button
                      onClick={handleNextMonth}
                      className="p-1 hover:bg-slate-100 rounded text-slate-600 transition-colors"
                    >
                      <ChevronRight className="w-4 h-4" />
                    </button>
                  </div>
                </div>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={showCompleted}
                    onChange={(e) => setShowCompleted(e.target.checked)}
                    className="!w-4 !h-4 !p-0 rounded border-slate-300 text-brand-600 focus:ring-brand-500"
                  />
                  <span className="text-sm text-slate-700 font-medium">Отображать завершенные недели</span>
                </label>
              </div>
            </div>

            {sortedWeeks.map((weekStart) => {
              const weekShifts = groups.get(weekStart) ?? [];
              const weekVirtual = virtualGroups.get(weekStart) ?? [];
              const weekStatus = weekShifts[0]?.weekStatus ?? null;
              const dates = weekDates(weekStart);
              const endD = new Date(weekStart + "T00:00:00Z");
              endD.setUTCDate(endD.getUTCDate() + 6);
              const isPastWeek = endD.toISOString().slice(0, 10) < todayStr;

              const totalHours = weekShifts.reduce((sum, s) => {
                const [sh, sm] = s.startTime.split(":").map(Number);
                const [eh, em] = s.endTime.split(":").map(Number);
                let m = eh * 60 + em - (sh * 60 + sm);
                if (m <= 0) m += 24 * 60;
                return sum + m / 60;
              }, 0);

              return (
                <div key={weekStart} className={`mb-8 ${isPastWeek ? "opacity-60 grayscale-[30%]" : ""}`}>
                  <div className="flex items-center gap-3 mb-3 flex-wrap">
                    <h2 className="text-lg font-semibold text-slate-900">Неделя {shortDate(dates[0])} — {shortDate(dates[6])}</h2>
                    {weekStatus === "DRAFT" && <span className="text-xs px-2 py-0.5 rounded-full bg-slate-100 text-slate-600 ring-1 ring-slate-200 font-medium">черновик</span>}
                    {weekStatus === "PUBLISHED" && <span className="text-xs px-2 py-0.5 rounded-full bg-emerald-50 text-emerald-700 ring-1 ring-emerald-200 font-medium">опубликован</span>}
                    <span className="text-xs text-slate-500 ml-auto">{weekShifts.length} смен · {Math.round(totalHours * 10) / 10} ч</span>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 lg:grid-cols-7 gap-3">
                    {dates.map((date) => {
                      const dayShifts = weekShifts.filter((s) => String(s.shiftDate).slice(0, 10) === date);
                      const dayVirtual = weekVirtual.filter((v) => v.date === date);
                      const dayOffers = availableByDate.get(date) ?? [];
                      const hasAnything = dayShifts.length > 0 || dayVirtual.length > 0 || dayOffers.length > 0;
                      const isToday = date === new Date().toISOString().slice(0, 10);
                      return (
                        <div key={date} className={`bg-white rounded-2xl border shadow-sm p-3 min-h-[120px] flex flex-col transition-all ${isToday ? "border-brand-300 ring-2 ring-brand-500/10" : "border-slate-200"}`}>
                          <div className="mb-2 pb-2 border-b border-slate-100">
                            <div className="flex items-center justify-between">
                              <div className={`font-semibold text-sm ${isToday ? "text-brand-700" : "text-slate-900"}`}>{dayLabel(date)}</div>
                              {isToday && <span className="text-[10px] uppercase tracking-wide text-brand-600 font-semibold">сегодня</span>}
                            </div>
                            <div className="text-xs text-slate-500 mt-0.5">{shortDate(date)}</div>
                          </div>

                          <div className="space-y-2 flex-1">
                            {!hasAnything && <div className="text-xs text-slate-300 text-center py-3">—</div>}
                            
                            {mySickLeaves.filter(sl => String(sl.startDate).slice(0,10) <= date && String(sl.endDate).slice(0,10) >= date).map(sl => (
                              <div key={sl.id} className="text-xs p-2 rounded-lg border-l-4 border-rose-500 bg-rose-50 text-rose-900 mb-2">
                                <div className="flex items-center gap-1.5 font-medium">
                                  <Stethoscope className="w-3 h-3 text-rose-600 shrink-0" />
                                  Больничный
                                </div>
                                {sl.comment && <div className="text-[10px] text-rose-700/80 mt-0.5 truncate">{sl.comment}</div>}
                              </div>
                            ))}

                            {dayShifts.map((s) => {
                              const outgoingSwap = outgoingActive.find((r) => r.shiftId === s.id);
                              const isPublished = weekStatus === "PUBLISHED";
                              const pendingInc = pendingIncomingByShift.get(s.id);
                              const pendingOut = pendingOutgoingByShift.get(s.id);
                              const pending = pendingInc ?? pendingOut;
                              const hasAnyPending = !!pending;
                              const activeTimeOff = myTimeOffs.find(t => t.shiftId === s.id && t.status === "PENDING");

                              const oldDate = String(s.shiftDate).slice(0, 10);
                              const newDate = pending ? pending.newShiftDate.slice(0, 10) : oldDate;
                              const dateChanged = hasAnyPending && oldDate !== newDate;
                              const timeChanged = hasAnyPending && (s.startTime !== pending!.newStartTime || s.endTime !== pending!.newEndTime);

                              // Определяем стили карточки в зависимости от статуса
                              let cardClass = "bg-blue-50/40 border-blue-500";
                              if (pendingInc) cardClass = "bg-amber-50/60 border-amber-500 ring-2 ring-amber-300/50";
                              else if (activeTimeOff) cardClass = "bg-amber-50/60 border-amber-500 ring-2 ring-amber-300/50";
                              else if (outgoingSwap) cardClass = "bg-slate-50 border-slate-400 border-dashed ring-1 ring-slate-200";

                              return (
                                <div key={s.id} className={`text-xs p-2 rounded-lg border-l-4 transition-all ${cardClass}`}>
                                  <div className="flex items-center gap-1.5 font-medium text-slate-900 flex-wrap">
                                    <Clock className="w-3 h-3 text-blue-600 shrink-0" />
                                    {timeChanged ? <><span className="line-through text-slate-400">{s.startTime}–{s.endTime}</span><span className="text-slate-400 text-[10px]">→</span><span className="text-amber-800 font-semibold">{pending!.newStartTime}–{pending!.newEndTime}</span></> : <span>{s.startTime}–{s.endTime}</span>}
                                  </div>

                                  {s.templateName && <div className="text-slate-500 truncate mt-0.5">{s.templateName}</div>}

                                  {dateChanged && <div className="flex items-center gap-1 mt-1 text-[10px] flex-wrap"><CalendarDays className="w-2.5 h-2.5 text-slate-400 shrink-0" /><span className="line-through text-slate-400">{shortDate(oldDate)}</span><span className="text-slate-400">→</span><span className="text-amber-800 font-semibold">{shortDate(newDate)}</span></div>}

                                  {pendingInc && <div className="mt-1.5 flex items-center gap-1 text-[10px] font-semibold text-amber-800 bg-amber-100 rounded px-1.5 py-1 leading-tight"><Bell className="w-3 h-3 shrink-0" /><span>Требуется ваше согласие</span></div>}
                                  {pendingOut && !pendingInc && <div className="mt-1.5 flex items-center gap-1 text-[10px] font-medium text-slate-600 bg-slate-100 rounded px-1.5 py-1 leading-tight"><Clock className="w-3 h-3 shrink-0" /><span>Ожидает согласования</span></div>}
                                  
                                  {/* Блок Отгула */}
                                  {activeTimeOff && (
                                    <div className="mt-2 p-1.5 bg-amber-100 rounded border border-amber-200 animate-fade-in">
                                      <div className="text-[10px] font-semibold text-amber-800 mb-1">Запрос на отгул</div>
                                      {!isPastWeek && (
                                        <button onClick={() => onCancelTimeOff(activeTimeOff.id)} className="w-full bg-white text-rose-600 border border-rose-200 text-[10px] py-1 rounded hover:bg-rose-50 font-medium">Отменить отгул</button>
                                      )}
                                    </div>
                                  )}

                                  {/* Блок Обмена (исходящий) */}
                                  {outgoingSwap && (
                                    <div className="mt-2 p-1.5 bg-slate-100 rounded border border-slate-200 animate-fade-in">
                                      <div className="text-[10px] font-semibold text-slate-700 mb-1">Обмен предложен</div>
                                      {!isPastWeek && (
                                        <button onClick={() => onCancelSwap(outgoingSwap.id)} className="w-full bg-white text-rose-600 border border-rose-200 text-[10px] py-1 rounded hover:bg-rose-50 font-medium">Отменить обмен</button>
                                      )}
                                    </div>
                                  )}

                                  {isPublished && !outgoingSwap && !hasAnyPending && !activeTimeOff && !isPastWeek && (
                                    <div className="flex flex-wrap gap-2 mt-2 pt-2 border-t border-slate-100">
                                      <button onClick={() => openSwapModal(s)} className="inline-flex items-center gap-1 text-[10px] font-medium text-brand-600 hover:text-brand-700"><ArrowRightLeft className="w-3 h-3" /> Обмен</button>
                                      <button onClick={() => openEditShift(s)} className="inline-flex items-center gap-1 text-[10px] font-medium text-slate-500 hover:text-slate-700"><Pencil className="w-3 h-3" /> Изменить</button>
                                      <button onClick={() => onRequestTimeOff(s)} className="inline-flex items-center gap-1 text-[10px] font-medium text-amber-600 hover:text-amber-700 ml-auto"><CalendarX2 className="w-3 h-3" /> Отгул</button>
                                    </div>
                                  )}

                                  {pendingInc && pendingInc.requestedByName && <div className="mt-1 text-[10px] text-slate-500">от {pendingInc.requestedByName}</div>}
                                </div>
                              );
                            })}
                            
                            {dayOffers.map((a) => {
                              const isTargeted = !!a.swapWithUserId;
                              return (
                                <div
                                  key={`offer-${a.id}`}
                                  className="text-xs p-2 rounded-lg border-l-4 border-violet-500 bg-violet-50/60 ring-2 ring-violet-300/50"
                                >
                                  <div className="flex items-center gap-1.5 font-medium text-slate-900">
                                    <ArrowRightLeft className="w-3 h-3 text-violet-600 shrink-0" />
                                    <span>{a.startTime}–{a.endTime}</span>
                                  </div>
                                  <div className="text-slate-700 text-[11px] truncate mt-0.5">
                                    {a.requestedByName ?? "Сотрудник"}
                                  </div>
                                  <div className="mt-1.5 flex items-center gap-1 text-[10px] font-semibold text-violet-800 bg-violet-100 rounded px-1.5 py-1 leading-tight">
                                    <ArrowRightLeft className="w-3 h-3 shrink-0" />
                                    <span>Предлагают обмен{isTargeted ? " (вам)" : ""}</span>
                                  </div>
                                                    <div className="flex gap-1.5 mt-2">
                    <button
                      onClick={() => onAccept(a.id)}
                      title="Принять"
                      className="flex-1 inline-flex items-center justify-center bg-emerald-600 text-white py-1.5 rounded-lg hover:bg-emerald-700 shadow-sm transition-colors"
                    >
                      <Check className="w-3.5 h-3.5" />
                    </button>
                    <button
                      onClick={() => onDecline(a.id)}
                      title={isTargeted ? "Отклонить" : "Скрыть"}
                      className="flex-1 inline-flex items-center justify-center bg-white text-rose-600 border border-rose-200 py-1.5 rounded-lg hover:bg-rose-50 transition-colors"
                    >
                      <X className="w-3.5 h-3.5" />
                    </button>
                  </div>
                                </div>
                              );
                            })}

                            {dayVirtual.map((v) => (
                              <div key={v.id} className={`text-xs p-2 rounded-lg border-l-4 ring-2 ${v.kind === "CREATE" ? "bg-amber-50/60 border-amber-500 ring-amber-300/50" : "bg-orange-50/60 border-orange-500 ring-orange-300/50"}`}>
                                <div className="flex items-center gap-1.5 font-medium text-slate-900"><Clock className={`w-3 h-3 shrink-0 ${v.kind === "CREATE" ? "text-amber-600" : "text-orange-600"}`} /><span>{v.startTime}–{v.endTime}</span></div>
                                {v.kind === "CREATE" && <div className="mt-1.5 flex items-center gap-1 text-[10px] font-semibold text-amber-800 bg-amber-100 rounded px-1.5 py-1 leading-tight"><Bell className="w-3 h-3 shrink-0" /><span>Новая смена от {v.fromName}</span></div>}
                                {v.kind === "SWAP" && <div className="mt-1.5 flex items-center gap-1 text-[10px] font-semibold text-orange-800 bg-orange-100 rounded px-1.5 py-1 leading-tight"><ArrowRightLeft className="w-3 h-3 shrink-0" /><span>Обмен от {v.fromName}</span></div>}
                                <div className="mt-1 text-[10px] text-slate-500">{v.kind === "CREATE" ? "Согласовать можно в блоке сверху" : "Согласовать можно в блоке входящих предложений"}</div>
                              </div>
                            ))}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              );
            })}
          </>
        )}

        {tab === "vacations" && (
          <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-5 mb-6">
            <div className="flex items-center justify-between mb-3 flex-wrap gap-2">
              <h3 className="font-semibold text-slate-900 flex items-center gap-2"><Palmtree className="w-4 h-4 text-emerald-600" /> Мои отпуска {upcomingVacations.length > 0 && <span className="text-xs px-2 py-0.5 rounded-full bg-emerald-50 text-emerald-700 font-medium ring-1 ring-emerald-200">{upcomingVacations.length} предстоящих</span>}</h3>
              {!isFree && <button onClick={() => showVacForm ? closeVacForm() : openCreateForm()} className="inline-flex items-center gap-1.5 text-sm font-medium text-brand-600 hover:text-brand-700 px-3 py-1.5 rounded-lg hover:bg-brand-50 transition-colors"><Plus className="w-3.5 h-3.5" />{showVacForm ? "Отмена" : "Добавить отпуск"}</button>}
              {isFree && <span className="text-xs text-amber-600 font-medium bg-amber-50 px-2 py-1 rounded-md">Доступно только на Pro</span>}
            </div>

            {showVacForm && (
              <form onSubmit={onSaveVacation} className="bg-slate-50 rounded-xl p-4 mb-3 space-y-3 animate-fade-in">
                {editingVacation && <div className="bg-blue-50 border border-blue-200 rounded-lg px-3 py-2 text-xs text-blue-800"><b>Редактирование отпуска.</b> После сохранения изменения отправятся на согласование руководителю.</div>}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                  <div><label className="block text-xs font-medium text-slate-600 mb-1">Дата начала</label><input type="date" value={vacForm.startDate} onChange={(e) => setVacForm((f) => ({ ...f, startDate: e.target.value }))} required /></div>
                  <div><label className="block text-xs font-medium text-slate-600 mb-1">Дата окончания</label><input type="date" value={vacForm.endDate} onChange={(e) => setVacForm((f) => ({ ...f, endDate: e.target.value }))} required /></div>
                </div>
                <div><label className="block text-xs font-medium text-slate-600 mb-1">Комментарий</label><input value={vacForm.comment} onChange={(e) => setVacForm((f) => ({ ...f, comment: e.target.value }))} placeholder="Ежегодный оплачиваемый" maxLength={255} /></div>
                <div className="flex gap-2">
                  <button type="submit" disabled={vacBusy} className="inline-flex items-center gap-2 bg-brand-600 text-white px-4 py-2 rounded-xl hover:bg-brand-700 disabled:opacity-50 text-sm font-medium transition-colors">{vacBusy ? "Сохранение..." : editingVacation ? "Отправить на согласование" : "Сохранить"}</button>
                  <button type="button" onClick={closeVacForm} className="px-4 py-2 rounded-xl text-slate-600 hover:bg-slate-100 text-sm font-medium transition-colors">Отмена</button>
                </div>
              </form>
            )}

            {myVacations.length === 0 ? (
              <p className="text-sm text-slate-500 py-2">У вас пока нет отпусков. Добавьте дату — руководитель увидит её при составлении графика.</p>
            ) : (
              <div className="space-y-2 mb-4">
                {myVacations.map((v) => {
                  const isPast = v.endDate < today;
                  const isPending = v.status === "PENDING";
                  let borderColor = "border-emerald-500"; let bgColor = "bg-emerald-50/40";
                  if (isPast) { borderColor = "border-slate-300"; bgColor = "bg-slate-50 opacity-70"; }
                  else if (isPending) { borderColor = "border-amber-500"; bgColor = "bg-amber-50/40"; }
                  return (
                    <div key={v.id} className={`flex items-center justify-between gap-3 border-l-4 pl-3 py-2 rounded-r-lg ${borderColor} ${bgColor}`}>
                      <div className="text-sm min-w-0 flex-1">
                        <div className="font-medium text-slate-900 flex items-center gap-2 flex-wrap">{formatShortDate(v.startDate)} — {formatShortDate(v.endDate)}{isPending && <span className="inline-flex items-center gap-1 text-[10px] uppercase tracking-wide px-2 py-0.5 rounded-full bg-amber-100 text-amber-700 font-semibold"><AlertCircle className="w-3 h-3" />На согласовании</span>}</div>
                        {v.comment && <div className="text-xs text-slate-500 truncate mt-0.5">{v.comment}</div>}
                      </div>
                      <div className="flex items-center gap-1 shrink-0">
                        {!isPast && <button onClick={() => openEditForm(v)} className="text-slate-400 hover:text-brand-600 hover:bg-brand-50 p-1.5 rounded-lg transition-colors" title="Редактировать"><Pencil className="w-3.5 h-3.5" /></button>}
                        {isPending ? (
                          <button onClick={() => onDeleteVacation(v.id)} className="text-amber-500 hover:text-amber-700 hover:bg-amber-50 p-1.5 rounded-lg transition-colors" title="Отменить запрос"><Undo2 className="w-3.5 h-3.5" /></button>
                        ) : (
                          <button onClick={() => onDeleteVacation(v.id)} className="text-slate-400 hover:text-red-600 hover:bg-red-50 p-1.5 rounded-lg transition-colors" title="Удалить"><X className="w-3.5 h-3.5" /></button>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}

            {myVacations.length > 0 && user && (
              <div className="mt-2">
                <VacationsGantt users={[{ id: user.id, name: user.name ?? user.email ?? "Сотрудник" }]} vacations={myVacations} canEdit={(v) => v.status === "APPROVED" && v.userId === user.id} onBarClick={(v) => { if (v.status === "APPROVED" && v.userId === user.id) openEditForm(v); }} onUpdate={onGanttUpdate} />
              </div>
            )}
          </div>
        )}
        {tab === "sick" && (
          <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-5 mb-6">
            <div className="flex items-center justify-between mb-3 flex-wrap gap-2">
              <h3 className="font-semibold text-slate-900 flex items-center gap-2">
                <Stethoscope className="w-4 h-4 text-rose-600" /> Мои больничные
              </h3>
            </div>

            {mySickLeaves.length === 0 ? (
              <p className="text-sm text-slate-500 py-2">У вас нет записей о больничных.</p>
            ) : (
              <div className="space-y-2 mb-4">
                {mySickLeaves.map((s) => (
                  <div key={s.id} className="flex items-center justify-between gap-3 border-l-4 pl-3 py-2 rounded-r-lg border-rose-500 bg-rose-50/40">
                    <div className="text-sm min-w-0 flex-1">
                      <div className="font-medium text-slate-900">
                        {formatShortDate(s.startDate)} — {formatShortDate(s.endDate)}
                      </div>
                      {s.comment && <div className="text-xs text-slate-500 truncate mt-0.5">{s.comment}</div>}
                    </div>
                  </div>
                ))}
              </div>
            )}

            {mySickLeaves.length > 0 && user && (
              <div className="mt-2">
                <VacationsGantt
                  users={[{ id: user.id, name: user.name ?? user.email ?? "Сотрудник" }]}
                  vacations={mySickLeaves.map(toGanttVacation)}
                  canEdit={() => false}
                  barTooltip={(v) => `Больничный: ${formatShortDate(v.startDate)} — ${formatShortDate(v.endDate)}`}
                />
              </div>
            )}
          </div>
        )}

      </main>

      {swapShift && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4" onClick={closeSwapModal}>
          <div className="bg-white rounded-2xl shadow-xl border border-slate-200 max-w-md w-full p-6 animate-fade-in" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-start justify-between mb-4">
              <div><h3 className="font-semibold text-slate-900 text-lg">Предложить обмен</h3><p className="text-sm text-slate-500 mt-0.5">{String(swapShift.shiftDate).slice(0, 10)} · {swapShift.startTime}–{swapShift.endTime}</p></div>
              <button onClick={closeSwapModal} className="text-slate-400 hover:text-slate-700 p-1 rounded-lg hover:bg-slate-100"><X className="w-4 h-4" /></button>
            </div>
            <div className="space-y-3 mb-6">
              <label className={`flex items-start gap-3 p-3 rounded-xl border-2 transition-all cursor-pointer hover:bg-slate-50 ${swapTarget === "" ? "border-brand-500 bg-brand-50/30" : "border-slate-200"}`}>
                <input type="radio" name="swap-target" value="" checked={swapTarget === ""} onChange={() => setSwapTarget("")} className="!w-4 !h-4 mt-1 !p-0" />
                <div><div className="font-medium text-slate-900 text-sm">Открытая смена</div><div className="text-xs text-slate-500 mt-0.5">Любой сотрудник сможет взять её</div></div>
              </label>
              {otherColleagues.length > 0 && (
                <div className="pt-2">
                  <div className="text-xs font-medium text-slate-500 uppercase tracking-wide mb-2">Или конкретный сотрудник</div>
                  <div className="space-y-1.5 max-h-60 overflow-y-auto">
                    {otherColleagues.map((c) => (
                      <label key={c.id} className={`flex items-center gap-3 p-2.5 rounded-xl border-2 cursor-pointer transition-all hover:bg-slate-50 ${swapTarget === c.id ? "border-brand-500 bg-brand-50/30" : "border-slate-200"}`}>
                        <input type="radio" name="swap-target" value={c.id} checked={swapTarget === c.id} onChange={() => setSwapTarget(c.id)} className="!w-4 !h-4 !p-0" />
                        <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-slate-600 text-xs font-semibold shrink-0">{c.name.split(" ").map((p) => p[0]).slice(0, 2).join("").toUpperCase()}</div>
                        <div className="min-w-0"><div className="font-medium text-slate-900 text-sm truncate">{c.name}</div><div className="text-xs text-slate-500 truncate">{c.email}</div></div>
                      </label>
                    ))}
                  </div>
                </div>
              )}
            </div>
            <div className="flex gap-3">
              <button onClick={onConfirmSwap} disabled={swapBusy} className="flex-1 inline-flex items-center justify-center gap-2 bg-brand-600 text-white px-4 py-2.5 rounded-xl hover:bg-brand-700 disabled:opacity-50 text-sm font-medium transition-all"><Send className="w-4 h-4" />{swapBusy ? "..." : "Отправить предложение"}</button>
              <button onClick={closeSwapModal} className="px-4 py-2.5 rounded-xl text-slate-600 hover:bg-slate-100 text-sm font-medium transition-colors">Отмена</button>
            </div>
          </div>
        </div>
      )}

      {editShift && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4" onClick={closeEditShift}>
          <div className="bg-white rounded-2xl shadow-xl border border-slate-200 max-w-md w-full p-6 animate-fade-in" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-start justify-between mb-4">
              <div><h3 className="font-semibold text-slate-900 text-lg">Изменить смену</h3><p className="text-sm text-slate-500 mt-0.5">Изменение уйдёт на согласование руководителю</p></div>
              <button onClick={closeEditShift} className="text-slate-400 hover:text-slate-700 p-1 rounded-lg hover:bg-slate-100"><X className="w-4 h-4" /></button>
            </div>
            <div className="space-y-4 mb-6">
              <div><label className="block text-sm font-medium text-slate-700 mb-1.5">Дата</label><input type="date" value={editForm.shiftDate} onChange={(e) => setEditForm((f) => ({ ...f, shiftDate: e.target.value }))} /></div>
              <div className="grid grid-cols-2 gap-3">
                <div><label className="block text-sm font-medium text-slate-700 mb-1.5">Начало</label><input type="time" value={editForm.startTime} onChange={(e) => setEditForm((f) => ({ ...f, startTime: e.target.value }))} /></div>
                <div><label className="block text-sm font-medium text-slate-700 mb-1.5">Конец</label><input type="time" value={editForm.endTime} onChange={(e) => setEditForm((f) => ({ ...f, endTime: e.target.value }))} /></div>
              </div>
            </div>
            <div className="flex gap-3">
              <button onClick={onSubmitEditShift} disabled={editBusy} className="flex-1 inline-flex items-center justify-center gap-2 bg-brand-600 text-white px-4 py-2.5 rounded-xl hover:bg-brand-700 disabled:opacity-50 text-sm font-medium transition-all"><Send className="w-4 h-4" />{editBusy ? "..." : "Отправить на согласование"}</button>
              <button onClick={closeEditShift} className="px-4 py-2.5 rounded-xl text-slate-600 hover:bg-slate-100 text-sm font-medium transition-colors">Отмена</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

