}

frontend/src/pages/ProfilePage.tsx:
import { useEffect, useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import {
  Mail, Phone, Coins, Shield, KeyRound, Save, CalendarDays, Building2,
  Lock, Pencil, Settings as SettingsIcon, Clock, Percent, Palette, AlertCircle,
  Bell, Send, MessageSquare, Check, Loader2, X, User as UserIcon, Info, HelpCircle, CheckCircle2, Database, Eye, EyeOff,
} from "lucide-react";
import { useAuth } from "../store/auth";
import { useUsers } from "../store/users";
import { usersApi } from "../api/users";
import { api } from "../api/client";
import {
  meApi,
  type MyProfile,
  type MessengerProvider,
  type NotificationSettings,
  DEFAULT_NOTIFICATION_SETTINGS,
} from "../api/me";
import { organizationApi, type Organization } from "../api/organization";
import { useOrganization } from "../store/organization";
import { alertDialog } from "../store/dialogs";
import NavBar from "../components/NavBar";
import { Download } from "lucide-react";

// ─── Схема смены пароля ────────────────────────────
const passwordSchema = z
  .object({
    oldPassword: z.string().min(1, "Введите текущий пароль"),
    newPassword: z.string().min(8, "Минимум 8 символов"),
    confirmPassword: z.string().min(8, "Минимум 8 символов"),
  })
  .refine((d) => d.newPassword === d.confirmPassword, {
    message: "Пароли не совпадают",
    path: ["confirmPassword"],
  });
type PasswordForm = z.infer<typeof passwordSchema>;

const ROLE_LABELS: Record<string, string> = {
  OWNER: "Владелец",
  MANAGER: "Менеджер",
  EMPLOYEE: "Сотрудник",
};
const ROLE_BADGES: Record<string, string> = {
  OWNER: "bg-violet-50 text-violet-700 ring-1 ring-violet-200",
  MANAGER: "bg-blue-50 text-blue-700 ring-1 ring-blue-200",
  EMPLOYEE: "bg-slate-100 text-slate-700 ring-1 ring-slate-200",
};

// ─── Разделы ───────────────────────────────────────
type SectionId =
  | "profile" | "messenger"
  | "requisites" | "modules" | "approval" | "overtime" | "tax" | "appearance" | "passwords";

type Section = {
  id: SectionId;
  label: string;
  icon: React.ElementType;
  group: "personal" | "org";
};

const SECTIONS: Section[] = [
  { id: "profile", label: "Профиль", icon: Shield, group: "personal" },
  { id: "messenger", label: "Мессенджер", icon: MessageSquare, group: "personal" },
  { id: "requisites", label: "Реквизиты", icon: Building2, group: "org" },
  { id: "modules", label: "Модули", icon: SettingsIcon, group: "org" },
  { id: "approval", label: "Согласование", icon: Check, group: "org" },
  { id: "overtime", label: "Переработки", icon: Percent, group: "org" },
  { id: "tax", label: "Налоги", icon: Percent, group: "org" },
  { id: "appearance", label: "Внешний вид", icon: Palette, group: "org" },
  { id: "passwords", label: "Доступы и пароли", icon: KeyRound, group: "org" },
];

function initials(name: string): string {
  return name.split(" ").map((p) => p[0]).slice(0, 2).join("").toUpperCase();
}

// ═══════════════════════════════════════════════════
// Главный компонент
// ═══════════════════════════════════════════════════
export default function ProfilePage() {
  const { changePassword, user } = useAuth();
  const isAdmin = user?.email === import.meta.env.VITE_ADMIN_EMAIL;
  const [profile, setProfile] = useState<MyProfile | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [section, setSection] = useState<SectionId>("profile");
  const [showPass, setShowPass] = useState(false);

  const [org, setOrg] = useState<Organization | null>(null);
  const [orgForm, setOrgForm] = useState({
    name: "",
    city: "",
    directorName: "",
    inn: "",
    legalAddress: "",
    overtimeMultiplier1: "1.5",
    overtimeMultiplier2: "2.0",
    taxRate: "13",
    positionHeaderOpacity: 70,
    positionRowOpacity: 20,
    requireShiftApproval: true,
    disciplineEditWindowDays: 3,
  });
  const [orgEditing, setOrgEditing] = useState(false);
  const [orgSaving, setOrgSaving] = useState(false);
  const [togglingTime, setTogglingTime] = useState(false);

  const {
    register,
    handleSubmit,
    reset,
    formState: { errors },
  } = useForm<PasswordForm>({ resolver: zodResolver(passwordSchema) });

  const isOwner = profile?.role === "OWNER";

  const downloadJsonBackup = async () => {
    try {
      const res = await fetch("/api/organization/export-json", {
        headers: { Authorization: `Bearer ${localStorage.getItem("token")}` },
      });
      if (!res.ok) throw new Error("Ошибка выгрузки");
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `backup_${new Date().toISOString().slice(0, 10)}.json`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
    } catch (e) {
      alert("Не удалось скачать бэкап. Убедитесь, что у вас тариф Business.");
    }
  };

  useEffect(() => {
    Promise.all([
      meApi.profile().catch(() => null),
      organizationApi.get().catch(() => null),
    ])
      .then(([p, o]) => {
        setProfile(p);
        setOrg(o);
        if (o) {
          setOrgForm({
            name: o.name ?? "",
            city: o.city ?? "",
            directorName: o.directorName ?? "",
            inn: o.inn ?? "",
            legalAddress: o.legalAddress ?? "",
            overtimeMultiplier1: o.overtimeMultiplier1 ?? "1.5",
            overtimeMultiplier2: o.overtimeMultiplier2 ?? "2.0",
            taxRate: (o as any).taxRate ?? "13",
            positionHeaderOpacity: (o as any).positionHeaderOpacity ?? 70,
            positionRowOpacity: (o as any).positionRowOpacity ?? 20,
            requireShiftApproval: (o as any).requireShiftApproval ?? true,
            disciplineEditWindowDays: (o as any).disciplineEditWindowDays ?? 3,
          });
          useOrganization.getState().set(o);
        }
      })
      .finally(() => setLoading(false));
  }, []);

  // Если не owner — сбрасываем вкладку, если она из группы "Организация"
  useEffect(() => {
    const current = SECTIONS.find((s) => s.id === section);
    if (current?.group === "org" && !isOwner) setSection("profile");
  }, [isOwner, section]);

  const onSubmitPassword = async (data: PasswordForm) => {
    setSaving(true);
    try {
      await changePassword(data.oldPassword, data.newPassword);
      await alertDialog("Пароль успешно изменён", { variant: "success" });
      reset();
    } catch (e: any) {
      await alertDialog(e.response?.data?.error ?? "Ошибка смены пароля", {
        variant: "error",
      });
    } finally {
      setSaving(false);
    }
  };

  const savePartialOrg = async (patch: Record<string, any>) => {
    setOrgSaving(true);
    try {
      const updated = await organizationApi.update(patch as any);
      setOrg(updated);
      useOrganization.getState().set(updated);
      await alertDialog("Сохранено", { variant: "success" });
    } catch (err: any) {
      await alertDialog(err.response?.data?.error ?? "Ошибка сохранения", {
        variant: "error",
      });
    } finally {
      setOrgSaving(false);
    }
  };

  const onToggleTimeTracking = async (enabled: boolean) => {
    if (!org || !isOwner) return;
    const previous = org;
    const optimistic: Organization = { ...org, timeTrackingEnabled: enabled };
    setOrg(optimistic);
    useOrganization.getState().set(optimistic);
    setTogglingTime(true);

    try {
      const updated = await organizationApi.update({ timeTrackingEnabled: enabled });
      setOrg(updated);
      useOrganization.getState().set(updated);
    } catch (err: any) {
      setOrg(previous);
      useOrganization.getState().set(previous);
      await alertDialog(err.response?.data?.error ?? "Ошибка сохранения", {
        variant: "error",
      });
    } finally {
      setTogglingTime(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50">
      <NavBar />

      <main className="max-w-6xl mx-auto px-4 sm:px-6 py-8">
        
        <h1 className="text-3xl font-bold text-slate-900 mb-1">Профиль</h1>
        <p className="text-sm text-slate-500 mb-6">
          Личные данные, мессенджеры и настройки организации
        </p>

        {loading && <p className="text-slate-500 text-sm">Загрузка...</p>}

        {profile && (
          <div className="grid grid-cols-1 lg:grid-cols-[240px_1fr] gap-6">
            {/* ─── Сайдбар ─── */}
            <aside className="lg:sticky lg:top-24 self-start">
              <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-2 space-y-3">
                <SidebarGroup
                  title="Личное"
                  sections={SECTIONS.filter((s) => s.group === "personal")}
                  active={section}
                  onSelect={setSection}
                />
                {isOwner && (
                  <SidebarGroup
                    title="Организация"
                    sections={SECTIONS.filter((s) => s.group === "org")}
                    active={section}
                    onSelect={setSection}
                  />
                )}

                {/* 🔥 Кнопка для админа сервиса */}
                {user?.email === import.meta.env.VITE_ADMIN_EMAIL && (
                  <div className="pt-3 mt-3 border-t border-slate-100">
                    <div className="px-3 py-1.5 text-[10px] uppercase tracking-wide font-semibold text-brand-600">
                      Администратор
                    </div>
                    <button
                      onClick={() => window.location.href = "/admin-database"}
                      className="w-full flex items-center gap-2.5 px-3 py-2 rounded-xl text-sm font-medium transition-colors text-left bg-slate-900 text-white hover:bg-slate-800"
                    >
                      <Database className="w-4 h-4 shrink-0 text-brand-400" />
                      <span className="truncate">База организаций</span>
                    </button>
                  </div>
                )}
              </div>
            </aside>

            {/* ─── Контент ─── */}
            <div className="min-w-0">
              {section === "profile" && (
                <ProfileSection
                  profile={profile}
                  saving={saving}
                  register={register}
                  errors={errors}
                  onSubmit={handleSubmit(onSubmitPassword)}
                />
              )}

              {section === "messenger" && (
                <MessengerSection userId={profile.id} />
              )}

              {section === "modules" && isOwner && org?.tariffId === "business" && (
                <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-6 animate-fade-in mb-6">
                  <h2 className="font-semibold text-slate-900 mb-2">Выгрузка данных (JSON)</h2>
                  <p className="text-sm text-slate-500 mb-4">Скачайте полную резервную копию всех данных вашей организации.</p>
                  <button onClick={downloadJsonBackup} className="inline-flex items-center gap-2 bg-slate-900 text-white px-4 py-2 rounded-xl hover:bg-slate-800 text-sm font-medium">
                    <Download className="w-4 h-4" /> Скачать JSON
                  </button>
                </div>
              )}

              {section === "requisites" && isOwner && org && (
                <RequisitesSection
                  org={org}
                  form={orgForm}
                  setForm={setOrgForm}
                  editing={orgEditing}
                  setEditing={setOrgEditing}
                  saving={orgSaving}
                  onSave={() =>
                    savePartialOrg({
                      name: orgForm.name || undefined,
                      city: orgForm.city || null,
                      directorName: orgForm.directorName || null,
                      inn: orgForm.inn || null,
                      legalAddress: orgForm.legalAddress || null,
                    }).then(() => setOrgEditing(false))
                  }
                />
              )}

              {section === "modules" && isOwner && org && (
                <ModulesSection
                  timeTrackingOn={org.timeTrackingEnabled === true}
                  toggling={togglingTime}
                  onToggle={onToggleTimeTracking}
                />
              )}

              {section === "approval" && isOwner && org && (
                <ApprovalSection
                  form={orgForm}
                  setForm={setOrgForm}
                  saving={orgSaving}
                  onSave={() =>
                    savePartialOrg({
                      requireShiftApproval: orgForm.requireShiftApproval,
                      disciplineEditWindowDays: orgForm.disciplineEditWindowDays,
                    })
                  }
                />
              )}

              {section === "overtime" && isOwner && org && (
                <OvertimeSection
                  form={orgForm}
                  setForm={setOrgForm}
                  saving={orgSaving}
                  onSave={() =>
                    savePartialOrg({
                      overtimeMultiplier1: orgForm.overtimeMultiplier1,
                      overtimeMultiplier2: orgForm.overtimeMultiplier2,
                    })
                  }
                />
              )}

              {section === "tax" && isOwner && org && (
                <TaxSection
                  form={orgForm}
                  setForm={setOrgForm}
                  saving={orgSaving}
                  onSave={() => savePartialOrg({ taxRate: orgForm.taxRate })}
                />
              )}

              {section === "passwords" && isOwner && (
                <PasswordsSection />
              )}

              {section === "appearance" && isOwner && org && (
                <AppearanceSection
                  form={orgForm}
                  setForm={setOrgForm}
                  saving={orgSaving}
                  onSave={() =>
                    savePartialOrg({
                      positionHeaderOpacity: orgForm.positionHeaderOpacity,
                      positionRowOpacity: orgForm.positionRowOpacity,
                    })
                  }
                />
              )}
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

// ═══════════════════════════════════════════════════
// Сайдбар
// ═══════════════════════════════════════════════════
function SidebarGroup({
  title,
  sections,
  active,
  onSelect,
}: {
  title: string;
  sections: Section[];
  active: SectionId;
  onSelect: (id: SectionId) => void;
}) {
  return (
    <div>
      <div className="px-3 py-1.5 text-[10px] uppercase tracking-wide font-semibold text-slate-400">
        {title}
      </div>
      <div className="space-y-0.5">
        {sections.map((s) => {
          const Icon = s.icon;
          const isActive = active === s.id;
          return (
            <button
              key={s.id}
              onClick={() => onSelect(s.id)}
              className={`w-full flex items-center gap-2.5 px-3 py-2 rounded-xl text-sm font-medium transition-colors text-left ${
                isActive
                  ? "bg-brand-50 text-brand-700"
                  : "text-slate-600 hover:bg-slate-50"
              }`}
            >
              <Icon className={`w-4 h-4 shrink-0 ${isActive ? "text-brand-600" : "text-slate-400"}`} />
              <span className="truncate">{s.label}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════
// Профиль (карточка + смена пароля)
// ═══════════════════════════════════════════════════
function ProfileSection({
  profile, saving, register, errors, onSubmit,
}: {
  profile: MyProfile;
  saving: boolean;
  register: any;
  errors: any;
  onSubmit: (e: React.FormEvent) => void;
}) {
  return (
    <div className="space-y-6 animate-fade-in">
      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="h-20 bg-gradient-to-br from-brand-500 to-brand-700" />
        <div className="px-6 pb-6">
          <div className="flex items-start gap-4 mb-4">
            <div className="-mt-10 w-20 h-20 rounded-2xl bg-white shadow-md flex items-center justify-center text-2xl font-bold text-brand-600 border-4 border-white shrink-0">
              {initials(profile.name)}
            </div>
            <div className="pt-1 min-w-0">
              <div className="text-xl font-semibold text-slate-900 truncate">
                {profile.name}
              </div>
              <span className={`inline-flex items-center gap-1.5 text-xs px-2.5 py-0.5 rounded-full font-medium mt-1 ${ROLE_BADGES[profile.role]}`}>
                <Shield className="w-3 h-3" />
                {ROLE_LABELS[profile.role]}
              </span>
            </div>
          </div>

          {profile.tempPassword && (
            <div className="mt-4 bg-blue-50 border border-blue-200 rounded-xl p-4">
              <div className="flex items-center justify-between gap-4">
                <div>
                  <div className="text-xs font-semibold text-blue-900 mb-1">Пароль для входа</div>
                  <div className="flex items-center gap-2">
                    <input 
                      type={showPass ? "text" : "password"} 
                      value={profile.tempPassword} 
                      readOnly 
                      className="!bg-white !border-blue-200 !text-sm !py-1.5 !px-3 !w-48 font-mono font-bold"
                    />
                    <button onClick={() => setShowPass(!showPass)} className="text-blue-600 hover:text-blue-800 p-1">
                      {showPass ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                    </button>
                  </div>
                </div>
                <div className="text-[10px] text-blue-700 max-w-[200px]">
                  Этот пароль сгенерирован автоматически. Вы можете сменить его ниже.
                </div>
              </div>
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-6">
            <ProfileField icon={Mail} label="Email" value={profile.email} />
            {profile.phone && (
              <ProfileField icon={Phone} label="Телефон" value={profile.phone} />
            )}
            {profile.hourlyRate && (
              <ProfileField
                icon={Coins}
                label="Ставка"
                value={`${profile.hourlyRate} ₽`}
              />
            )}
            <ProfileField
              icon={CalendarDays}
              label="В системе с"
              value={new Date(profile.createdAt).toLocaleDateString("ru-RU", {
                day: "numeric", month: "long", year: "numeric",
              })}
            />
          </div>
        </div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-6">
        <div className="flex items-center gap-3 mb-5">
          <div className="w-10 h-10 rounded-xl bg-amber-50 flex items-center justify-center">
            <KeyRound className="w-5 h-5 text-amber-600" />
          </div>
          <div>
            <h2 className="font-semibold text-slate-900">Сменить пароль</h2>
            <p className="text-xs text-slate-500">
              Минимум 8 символов. Используйте буквы, цифры и символы.
            </p>
          </div>
        </div>

        <form onSubmit={onSubmit} className="space-y-4 max-w-md">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1.5">Текущий пароль</label>
            <input type="password" {...register("oldPassword")} className="w-full" placeholder="••••••••" />
            {errors.oldPassword && (
              <p className="text-red-500 text-xs mt-1">{errors.oldPassword.message}</p>
            )}
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1.5">Новый пароль</label>
            <input type="password" {...register("newPassword")} className="w-full" placeholder="Минимум 8 символов" />
            {errors.newPassword && (
              <p className="text-red-500 text-xs mt-1">{errors.newPassword.message}</p>
            )}
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1.5">Повторите новый пароль</label>
            <input type="password" {...register("confirmPassword")} className="w-full" placeholder="••••••••" />
            {errors.confirmPassword && (
              <p className="text-red-500 text-xs mt-1">{errors.confirmPassword.message}</p>
            )}
          </div>

          <button
            type="submit"
            disabled={saving}
            className="inline-flex items-center gap-2 bg-brand-600 text-white px-5 py-2.5 rounded-xl hover:bg-brand-700 disabled:opacity-50 text-sm font-medium shadow-sm transition-all"
          >
            <Save className="w-4 h-4" />
            {saving ? "Сохранение..." : "Сохранить пароль"}
          </button>
        </form>
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════
// Мессенджер (привязка + уведомления)
// ═══════════════════════════════════════════════════
function MessengerSection({ userId }: { userId: string }) {
  const { org, set: setOrg } = useOrganization();
  const [bindings, setBindings] = useState<{ max: string }>(() => {
    const raw = localStorage.getItem(`messengers_${userId}`);
    if (raw) { try { return JSON.parse(raw); } catch {} }
    return { max: "" };
  });
  const [settings, setSettings] = useState<NotificationSettings>(DEFAULT_NOTIFICATION_SETTINGS);
  const [draftMax, setDraftMax] = useState(bindings.max);
  const [busy, setBusy] = useState(false);
  const [testing, setTesting] = useState(false);
  
  // Состояния для шагов
  const [botToken, setBotToken] = useState(org?.maxBotToken || "");
  const [botLink, setBotLink] = useState(org?.maxBotLink || "");
  const [savingToken, setSavingToken] = useState(false);
  const [savingLink, setSavingLink] = useState(false);
  const [broadcasting, setBroadcasting] = useState(false);

  const isStep1 = !!org?.maxBotToken;
  const isStep2 = !!org?.maxBotLink;
  const isStep3 = !!bindings.max;
  const isOwner = useAuth(s => s.user?.role) === "OWNER";

  // Исправление ссылки (добавляем https://max.ru/ если нет)
  const maxLink = org?.maxBotLink
    ? org.maxBotLink.startsWith("http")
      ? org.maxBotLink
      : `https://max.ru/${org.maxBotLink.replace("@", "")}`
    : null;

  useEffect(() => {
    meApi.profile().then((p: any) => {
      if (p?.notificationSettings && Object.keys(p.notificationSettings).length > 0) {
        setSettings({ ...DEFAULT_NOTIFICATION_SETTINGS, ...p.notificationSettings });
      }
    }).catch(() => {});
  }, []);

  useEffect(() => {
    if (org) {
      setBotToken(org.maxBotToken || "");
      setBotLink(org.maxBotLink || "");
    }
  }, [org?.maxBotToken, org?.maxBotLink]);

  const toggle = async (key: keyof NotificationSettings) => {
    const newSettings = { ...settings, [key]: !settings[key] };
    setSettings(newSettings);
    try { await meApi.updateNotifications(newSettings); } catch (e) { console.error(e); }
  };

  const handleSaveToken = async () => {
    if (!botToken.trim()) return;
    setSavingToken(true);
    try {
      const updated = await organizationApi.update({ maxBotToken: botToken.trim() });
      if (!updated.maxBotId) {
        throw new Error("Токен сохранен, но ID бота не получен. Проверьте правильность токена.");
      }
      setOrg(updated);
      await alertDialog("Токен сохранен, вебхук настроен", { variant: "success" });
    } catch (e: any) {
      await alertDialog(e.response?.data?.error ?? "Ошибка сохранения токена", { variant: "error" });
    } finally {
      setSavingToken(false);
    }
  };

  const handleSaveLink = async () => {
    if (!botLink.trim()) return;
    setSavingLink(true);
    try {
      const updated = await organizationApi.update({ maxBotLink: botLink.trim() });
      setOrg(updated);
      await alertDialog("Ссылка сохранена", { variant: "success" });
    } catch (e: any) {
      await alertDialog(e.response?.data?.error ?? "Ошибка сохранения ссылки", { variant: "error" });
    } finally {
      setSavingLink(false);
    }
  };

  const handleUnlockToken = () => setOrg({ ...org, maxBotToken: null } as any);
  const handleUnlockLink = () => setOrg({ ...org, maxBotLink: null } as any);

  const bind = async () => {
    const externalId = draftMax.trim();
    if (!externalId) return;
    setBusy(true);
    try {
      await meApi.bindMessenger({ provider: "max", externalId });
      const next = { max: externalId };
      setBindings(next);
      localStorage.setItem(`messengers_${userId}`, JSON.stringify(next));
      await alertDialog("Мессенджер привязан", { variant: "success" });
    } catch (e: any) {
      const errMsg = e.response?.data?.error;
      await alertDialog(typeof errMsg === "string" ? errMsg : "Ошибка привязки", { variant: "error" });
    } finally {
      setBusy(false);
    }
  };

  const test = async () => {
    setTesting(true);
    try {
      const res = await meApi.testMessenger();
      await alertDialog(
        res.success ? "Тестовое сообщение отправлено!" : "Не удалось отправить. Проверьте привязку.",
        { variant: res.success ? "success" : "error" }
      );
    } catch {
      await alertDialog("Ошибка отправки", { variant: "error" });
    } finally {
      setTesting(false);
    }
  };

  const broadcastLink = async () => {
    if (!botLink.trim()) return alert("Сначала укажите и сохраните ссылку на бота");
    if (!confirm("Разослать ссылку на бота всем сотрудникам на почту?")) return;
    setBroadcasting(true);
    try {
      const res = await api.post("/organization/broadcast-bot-link");
      await alertDialog(`Ссылка отправлена: ${res.data.sent} писем`, { variant: "success" });
    } catch (e: any) {
      await alertDialog(e.response?.data?.error ?? "Ошибка рассылки", { variant: "error" });
    } finally {
      setBroadcasting(false);
    }
  };

  return (
    <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-6 animate-fade-in">
      <div className="flex items-center gap-3 mb-5">
        <div className="w-10 h-10 rounded-xl bg-brand-50 flex items-center justify-center">
          <MessageSquare className="w-5 h-5 text-brand-600" />
        </div>
        <div>
          <h2 className="font-semibold text-slate-900">Мессенджер</h2>
          <p className="text-xs text-slate-500">Куда присылать уведомления о сменах</p>
        </div>
      </div>

      {isOwner && (
        <div className="mb-6">
          <details className="group cursor-pointer mb-4 bg-slate-50 p-4 rounded-xl border border-slate-200">
            <summary className="font-semibold text-brand-600 text-sm flex items-center gap-2 select-none hover:text-brand-700 transition-colors">
              <HelpCircle className="w-4 h-4" />
              Инструкция: Как создать и настроить своего бота в MAX?
            </summary>
            <div className="mt-3 text-[13px] text-slate-600 space-y-3 bg-white p-4 rounded-lg border border-slate-200 leading-relaxed">
              <div className="bg-rose-50 border border-rose-100 text-rose-800 p-3 rounded-md mb-2">
                <b>⚠️ Важно:</b> Раньше ботов создавали через @MasterBot. Теперь это делается <b>только</b> на официальной платформе «MAX для партнеров» (требуется статус ИП, самозанятого или юрлица).
              </div>
              <ol className="list-decimal pl-4 space-y-1.5">
                <li>Перейдите на платформу <a href="https://business.max.ru" target="_blank" rel="noopener noreferrer" className="text-brand-600 font-medium hover:underline">business.max.ru</a> и авторизуйтесь по российскому номеру телефона.</li>
                <li>Пройдите верификацию бизнеса (подтвердите статус ИП/юрлица).</li>
                <li>В личном кабинете выберите раздел <b>«Чат-боты»</b> и нажмите кнопку <b>«Создать»</b>.</li>
                <li>Заполните карточку бота (название, описание, логотип) и отправьте на модерацию.</li>
                <li>После одобрения модерацией скопируйте <b>Токен</b> и <b>Ссылку</b> на бота в его настройках.</li>
              </ol>
              <p className="mt-3 font-semibold text-slate-900 pt-2 border-t border-slate-100">
                Вставьте полученные токен и ссылку в поля ниже. Вебхук настроится автоматически.
              </p>
            </div>
          </details>

          {/* STEP 1: TOKEN */}
          <div className={`rounded-xl border-2 transition-all p-4 mb-3 ${isStep1 ? 'border-emerald-200 bg-emerald-50/20' : 'border-brand-200 bg-white'}`}>
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2">
                {isStep1 ? <CheckCircle2 className="w-5 h-5 text-emerald-500 shrink-0" /> : <div className="w-5 h-5 rounded-full bg-brand-100 text-brand-700 text-xs font-bold flex items-center justify-center shrink-0">1</div>}
                <h3 className="font-semibold text-slate-900 text-sm">Токен бота MAX</h3>
              </div>
              {isStep1 && (
                <button onClick={handleUnlockToken} className="text-xs text-brand-600 hover:underline flex items-center gap-1">
                  <Pencil className="w-3 h-3" /> Изменить
                </button>
              )}
            </div>
            <div className="flex gap-2">
              <input
                type="password"
                value={botToken}
                onChange={(e) => setBotToken(e.target.value)}
                placeholder="Например: 123456789:AAH..."
                className="w-full !text-sm"
                disabled={isStep1}
              />
              {!isStep1 && (
                <button onClick={handleSaveToken} disabled={savingToken || !botToken.trim()} className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm font-medium hover:bg-brand-700 disabled:opacity-50 whitespace-nowrap">
                  {savingToken ? "Сохранение..." : "Сохранить"}
                </button>
              )}
            </div>
          </div>

          {/* STEP 2: LINK */}
          <div className={`rounded-xl border-2 transition-all p-4 mb-3 ${!isStep1 ? 'opacity-50 border-slate-200 bg-slate-50 pointer-events-none' : isStep2 ? 'border-emerald-200 bg-emerald-50/20' : 'border-brand-200 bg-white'}`}>
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2">
                {isStep2 ? <CheckCircle2 className="w-5 h-5 text-emerald-500 shrink-0" /> : <div className="w-5 h-5 rounded-full bg-slate-200 text-slate-600 text-xs font-bold flex items-center justify-center shrink-0">2</div>}
                <div>
                  <h3 className="font-semibold text-slate-900 text-sm">Ссылка на вашего бота MAX</h3>
                  <p className="text-xs text-slate-500">Сотрудники увидят эту ссылку у себя в профиле.</p>
                </div>
              </div>
              {isStep2 && (
                <button onClick={handleUnlockLink} className="text-xs text-brand-600 hover:underline flex items-center gap-1">
                  <Pencil className="w-3 h-3" /> Изменить
                </button>
              )}
            </div>
            <div className="flex gap-2 mb-2">
              <input
                value={botLink}
                onChange={(e) => setBotLink(e.target.value)}
                placeholder="@username или https://max.ru/..."
                className="flex-1 !text-sm"
                disabled={!isStep1 || isStep2}
              />
              {!isStep2 && (
                <button onClick={handleSaveLink} disabled={savingLink || !botLink.trim()} className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm font-medium hover:bg-brand-700 disabled:opacity-50 whitespace-nowrap">
                  {savingLink ? "Сохранение..." : "Сохранить"}
                </button>
              )}
            </div>
            <button onClick={broadcastLink} disabled={broadcasting || !isStep2} className="w-full flex items-center justify-center gap-2 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg text-sm font-medium hover:bg-slate-50 disabled:opacity-50 transition-colors">
              <Send className="w-4 h-4" />
              {broadcasting ? "Отправка..." : "Разослать ссылку всем на почту"}
            </button>
          </div>
        </div>
      )}

      {/* STEP 3: BIND ID (Доступно всем, но с учетом лимитов) */}
      <div className={`rounded-xl border-2 transition-all p-4 mb-6 ${isOwner && !isStep2 ? 'opacity-50 border-slate-200 bg-slate-50 pointer-events-none' : isStep3 ? 'border-emerald-200 bg-emerald-50/20' : 'border-brand-200 bg-white'}`}>
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center gap-2">
            {isStep3 ? <CheckCircle2 className="w-5 h-5 text-emerald-500 shrink-0" /> : <div className="w-5 h-5 rounded-full bg-slate-200 text-slate-600 text-xs font-bold flex items-center justify-center shrink-0">3</div>}
            <div>
              <h3 className="font-semibold text-slate-900 text-sm">Ваш ID в MAX</h3>
              {!isOwner && <p className="text-xs text-slate-500">Чтобы получать уведомления о сменах</p>}
            </div>
          </div>
        </div>
        
        {maxLink ? (
          <div className="mb-3 bg-blue-50 border border-blue-200 rounded-lg p-2.5 flex items-start gap-2 text-xs text-blue-900">
            <Info className="w-4 h-4 shrink-0 text-blue-600" />
            <div>
              Перейдите в бота по ссылке: <a href={maxLink} target="_blank" rel="noopener noreferrer" className="font-bold underline hover:text-blue-700">{maxLink}</a><br/>
              Нажмите /start, скопируйте ID и вставьте ниже.
            </div>
          </div>
        ) : (
          <div className="mb-3 text-xs text-amber-600 bg-amber-50 p-2.5 rounded-lg border border-amber-200">
            Руководитель еще не настроил ссылку на бота. Попросите его сделать это.
          </div>
        )}

        <div className="flex gap-2">
          <input
            value={draftMax}
            onChange={(e) => setDraftMax(e.target.value)}
            placeholder="Например: 987654321"
            className="!text-sm flex-1"
            disabled={!maxLink || isStep3}
          />
          <button onClick={bind} disabled={!maxLink || !draftMax.trim() || busy || isStep3} className="inline-flex items-center gap-1.5 px-4 py-2 bg-brand-600 text-white rounded-lg hover:bg-brand-700 disabled:opacity-50 text-sm font-medium transition-colors whitespace-nowrap">
            {busy ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
            {isStep3 ? "Привязан" : "Привязать"}
          </button>
        </div>
        {isStep3 && (
           <div className="text-xs text-emerald-700 mt-2 flex items-center gap-1">
             <Check className="w-3.5 h-3.5" /> Успешно привязан ID: <span className="font-mono font-medium">{bindings.max}</span>
           </div>
        )}
      </div>

      {/* NOTIFICATIONS */}
      {isStep3 ? (
        <>
          <div className="mb-6">
            <button type="button" onClick={test} disabled={testing} className="inline-flex items-center gap-2 px-4 py-2 bg-slate-100 text-slate-700 rounded-xl hover:bg-slate-200 disabled:opacity-50 text-sm font-medium transition-colors">
              {testing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
              Отправить тестовое сообщение
            </button>
          </div>

          <div>
            <h3 className="font-semibold text-slate-900 mb-1 flex items-center gap-2">
              <Bell className="w-4 h-4 text-slate-500" /> Какие уведомления получать
            </h3>
            <p className="text-xs text-slate-500 mb-4">Отметьте события, о которых хотите получать сообщения</p>
            <div className="grid sm:grid-cols-2 gap-2">
              <NotifCheckbox label="Новый график на неделю" checked={settings.newSchedule} onChange={() => toggle("newSchedule")} />
              <NotifCheckbox label="Смена изменена" checked={settings.shiftChanged} onChange={() => toggle("shiftChanged")} />
              <NotifCheckbox label="Назначена новая смена" checked={settings.shiftCreated} onChange={() => toggle("shiftCreated")} />
              <NotifCheckbox label="Нужно согласовать изменение смены" checked={settings.shiftChangeApproval} onChange={() => toggle("shiftChangeApproval")} />
              <NotifCheckbox label="Запрос на обмен сменами" checked={settings.swapRequest} onChange={() => toggle("swapRequest")} />
              <NotifCheckbox label="Отпуск (одобрен/отклонён)" checked={settings.vacationReviewed} onChange={() => toggle("vacationReviewed")} />
              <NotifCheckbox label="Больничный" checked={settings.sickLeave} onChange={() => toggle("sickLeave")} />
              <NotifCheckbox label="Отгул (одобрен/отклонён)" checked={settings.timeOffReviewed} onChange={() => toggle("timeOffReviewed")} />
            </div>
            <div className="mt-6">
              <h4 className="font-semibold text-slate-900 mb-2 flex items-center gap-2">
                <Clock className="w-4 h-4 text-slate-500" /> Напоминания о начале смены
              </h4>
              <div className="grid sm:grid-cols-2 gap-2">
                <NotifCheckbox label="За час до начала" checked={settings.remindHour} onChange={() => toggle("remindHour")} />
                <NotifCheckbox label="За 5 минут до начала" checked={settings.remindFiveMin} onChange={() => toggle("remindFiveMin")} />
              </div>
            </div>
          </div>
        </>
      ) : (
        <div className="text-sm text-slate-500 text-center py-6 bg-slate-50 rounded-xl border border-slate-100">
          Настройки уведомлений станут доступны после того, как вы привяжете свой ID.
        </div>
      )}
    </div>
  );
}

