    if (items.length > 0) {
      await get().fetch();
    }
  },

  clockOut: async () => {
    await timeEntriesApi.clockOut();
    set({ active: null });
    const { items } = get();
    if (items.length > 0) {
      await get().fetch();
    }
  },
}));

