function getMondaysOfMonth(year: number, month: number): string[] {
  const first = new Date(Date.UTC(year, month, 1));
  const dow = first.getUTCDay(); // 0=Sun, 1=Mon
  const diff = dow === 1 ? 0 : dow === 0 ? -6 : 1 - dow;
