import ExcelJS from "exceljs";
import type { AnalyticsSummary } from "../../modules/analytics/analytics.service.js";

const ROLE_LABELS: Record<string, string> = {
  OWNER: "Владелец",
  MANAGER: "Менеджер",
  EMPLOYEE: "Сотрудник",
};

const MONEY_FMT = '#,##0 "₽"';
const HOURS_FMT = '#,##0.0 "ч"';

function setHeader(row: ExcelJS.Row) {
  row.font = { bold: true, color: { argb: "FFFFFFFF" }, size: 10 };
  row.fill = {
    type: "pattern",
    pattern: "solid",
    fgColor: { argb: "FF2563EB" },
  };
  row.alignment = { vertical: "middle", horizontal: "left" };
  row.height = 26;
}

function applyBordersAndZebra(sheet: ExcelJS.Worksheet) {
  sheet.eachRow((row, idx) => {
    row.eachCell((cell) => {
      cell.border = {
        top: { style: "thin", color: { argb: "FFE2E8F0" } },
        bottom: { style: "thin", color: { argb: "FFE2E8F0" } },
        left: { style: "thin", color: { argb: "FFE2E8F0" } },
        right: { style: "thin", color: { argb: "FFE2E8F0" } },
      };
      cell.alignment = { vertical: "middle" };
    });
    if (idx > 1 && idx % 2 === 0) {
      row.eachCell((cell) => {
        cell.fill = {
          type: "pattern",
          pattern: "solid",
          fgColor: { argb: "FFF8FAFC" },
        };
      });
    }
  });
}

export async function buildAnalyticsExcel(
  data: AnalyticsSummary
): Promise<Buffer> {
  const wb = new ExcelJS.Workbook();
  wb.creator = "Планировщик смен";
  wb.created = new Date();

  // ═══ Лист 1: Сводка ═══
  const s = wb.addWorksheet("Сводка");
  s.columns = [{ width: 36 }, { width: 24 }, { width: 16 }];

  s.mergeCells("A1:C1");
  s.getCell("A1").value = "Аналитика";
  s.getCell("A1").font = { bold: true, size: 18, color: { argb: "FF0F172A" } };
  s.getRow(1).height = 32;

  s.mergeCells("A2:C2");
  s.getCell("A2").value = `Период: ${data.period.from} — ${data.period.to}`;
  s.getCell("A2").font = { size: 11, color: { argb: "FF475569" } };

  s.mergeCells("A3:C3");
  s.getCell("A3").value = `Сравнение с: ${data.prevPeriod.from} — ${data.prevPeriod.to}`;
  s.getCell("A3").font = { size: 10, color: { argb: "FF94A3B8" }, italic: true };

  const headRow = s.getRow(5);
  headRow.values = ["Показатель", "Значение", "MoM"];
  setHeader(headRow);

  type Metric = [string, string | number, number | undefined, "money" | "number" | "pct"];
  const metrics: Metric[] = [
    ["План часов", data.totals.hours, data.totals.mom.hours, "number"],
    ["Смен", data.totals.shifts, data.totals.mom.shifts, "number"],
    ["План ФОТ", data.totals.payroll, data.totals.mom.payroll, "money"],
    ["Факт ФОТ", data.totals.actualPayroll, data.totals.mom.actualPayroll, "money"],
    ["Средняя цена смены", data.totals.avgCost, data.totals.mom.avgCost, "money"],
    ["Стоимость переработок", data.totals.overtimeCost, undefined, "money"],
    ["Фактические часы", data.planVsFact.actualHours, undefined, "number"],
    ["План vs Факт", data.planVsFact.diffPercent, undefined, "pct"],
  ];

  let r = 6;
  for (const [label, value, mom, kind] of metrics) {
    const row = s.getRow(r);
    row.values = [label, value, mom !== undefined ? mom : null];

    row.getCell(2).numFmt = kind === "money" ? MONEY_FMT : kind === "pct" ? "+0.0;-0.0;0.0" : "#,##0.0";
    row.getCell(2).alignment = { horizontal: "right" };

    if (mom !== undefined) {
      const cell = row.getCell(3);
      cell.numFmt = '+0.0"%";-0.0"%";0"%"';
      cell.alignment = { horizontal: "right" };
      cell.font = {
        bold: true,
        color: { argb: mom > 0 ? "FF16A34A" : mom < 0 ? "FFDC2626" : "FF94A3B8" },
      };
    } else {
      row.getCell(3).value = "—";
      row.getCell(3).alignment = { horizontal: "right" };
      row.getCell(3).font = { color: { argb: "FFCBD5E1" } };
    }
    r++;
  }

  applyBordersAndZebra(s);

  // ═══ Лист 2: Сотрудники ═══
  const u = wb.addWorksheet("Сотрудники");
  u.columns = [
    { header: "Сотрудник", key: "name", width: 28 },
    { header: "Роль", key: "role", width: 14 },
    { header: "Ставка, ₽/ч", key: "rate", width: 14, style: { numFmt: "#,##0" } },
    { header: "Смен", key: "shifts", width: 10, style: { numFmt: "#,##0" } },
    { header: "План ч", key: "planH", width: 12, style: { numFmt: HOURS_FMT } },
    { header: "Факт ч", key: "factH", width: 12, style: { numFmt: HOURS_FMT } },
    { header: "План ФОТ", key: "planPay", width: 16, style: { numFmt: MONEY_FMT } },
    { header: "Факт ФОТ", key: "factPay", width: 16, style: { numFmt: MONEY_FMT } },
    { header: "Переработка", key: "ot", width: 16, style: { numFmt: MONEY_FMT } },
  ];
  setHeader(u.getRow(1));

  for (const usr of data.users) {
    u.addRow({
      name: usr.name,
      role: ROLE_LABELS[usr.role] ?? usr.role,
      rate: usr.hourlyRate ?? null,
      shifts: usr.shiftsCount,
      planH: usr.plannedHours,
      factH: usr.actualHours,
      planPay: usr.plannedPayroll,
      factPay: usr.actualPayroll,
      ot: usr.overtimeCost || null,
    });
  }

  const totalRow = u.addRow({
    name: "ИТОГО",
    role: "",
    rate: null,
    shifts: data.totals.shifts,
    planH: data.totals.hours,
    factH: data.planVsFact.actualHours,
    planPay: data.totals.payroll,
    factPay: data.totals.actualPayroll,
    ot: data.totals.overtimeCost || null,
  });
  totalRow.font = { bold: true, color: { argb: "FF0F172A" } };
  totalRow.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FFEFF6FF" } };

  applyBordersAndZebra(u);

  // ═══ Лист 3: По дням недели ═══
  const w = wb.addWorksheet("По дням недели");
  w.columns = [
    { header: "День", key: "label", width: 12 },
    { header: "Смен", key: "shifts", width: 10, style: { numFmt: "#,##0" } },
    { header: "Часы", key: "hours", width: 12, style: { numFmt: HOURS_FMT } },
    { header: "ФОТ", key: "payroll", width: 18, style: { numFmt: MONEY_FMT } },
  ];
  setHeader(w.getRow(1));
  for (const d of data.byWeekday) {
    w.addRow({ label: d.label, shifts: d.shifts, hours: d.plannedHours, payroll: d.payroll });
  }
  applyBordersAndZebra(w);

  // ═══ Лист 4: По должностям ═══
  const p = wb.addWorksheet("По должностям");
  p.columns = [
    { header: "Должность", key: "position", width: 28 },
    { header: "Смен", key: "shifts", width: 10, style: { numFmt: "#,##0" } },
    { header: "Часы", key: "hours", width: 12, style: { numFmt: HOURS_FMT } },
    { header: "ФОТ", key: "payroll", width: 18, style: { numFmt: MONEY_FMT } },
    { header: "% от ФОТ", key: "percent", width: 12, style: { numFmt: '0.0"%"' } },
  ];
  setHeader(p.getRow(1));
  for (const pos of data.byPosition) {
    p.addRow({
      position: pos.position,
      shifts: pos.shifts,
      hours: pos.plannedHours,
      payroll: pos.payroll,
      percent: pos.percent,
    });
  }
  applyBordersAndZebra(p);

  return (await wb.xlsx.writeBuffer()) as Buffer;
}

src/lib/analytics/export-pdf.ts:
import { createRequire } from "node:module";
import type { AnalyticsSummary } from "../../modules/analytics/analytics.service.js";

const require = createRequire(import.meta.url);

const ROLE_LABELS: Record<string, string> = {
  OWNER: "Владелец",
  MANAGER: "Менеджер",
  EMPLOYEE: "Сотрудник",
};

const fmtMoney = (n: number) =>
  new Intl.NumberFormat("ru-RU").format(n) + " ₽";
const fmtPct = (n: number) => (n > 0 ? "+" : "") + n.toFixed(1) + "%";
const pctColor = (n: number) =>
  n > 0 ? "#16A34A" : n < 0 ? "#DC2626" : "#6B7280";

// ─── Инициализация PdfPrinter (кэшируется) ─────────────
// ─── Инициализация PdfPrinter (кэшируется) ─────────────
let printerInstance: any = null;
let initError: Error | null = null;

function getPrinter(): any {
  if (printerInstance) return printerInstance;
  if (initError) throw initError;

  try {
    const pdfMakeMod = require("pdfmake");

    // pdfmake 0.2.x: module.exports = PdfPrinter (сама функция)
    // pdfmake 0.3.x: module.exports = { PdfPrinter?, createPdf?, ... } или { default: ... }
    let PdfPrinter: any = null;

    if (typeof pdfMakeMod === "function") {
      // ← самый частый случай для 0.2.x
      PdfPrinter = pdfMakeMod;
    } else if (typeof pdfMakeMod?.PdfPrinter === "function") {
      PdfPrinter = pdfMakeMod.PdfPrinter;
    } else if (typeof pdfMakeMod?.default === "function") {
      PdfPrinter = pdfMakeMod.default;
    } else if (typeof pdfMakeMod?.default?.PdfPrinter === "function") {
      PdfPrinter = pdfMakeMod.default.PdfPrinter;
    }

    if (typeof PdfPrinter !== "function") {
      // Диагностика на случай, если всё ещё 0.3.x
      const diag =
        typeof pdfMakeMod === "object" && pdfMakeMod
          ? `keys: [${Object.keys(pdfMakeMod).join(", ")}], typeof: ${typeof pdfMakeMod}`
          : `typeof: ${typeof pdfMakeMod}`;
      throw new Error(
        `pdfmake: PdfPrinter не найден. ${diag}. ` +
          `Проверь версию: npm ls pdfmake (нужна 0.2.20)`
      );
    }

    // vfs_fonts.js в 0.2.x: module.exports = { pdfMake: { vfs: {...} } }
    // В некоторых сборках — просто { vfs: {...} } или { "Roboto-...ttf": "..." }
    const vfsMod = require("pdfmake/build/vfs_fonts.js");
    const vfs =
      vfsMod?.pdfMake?.vfs ??
      vfsMod?.vfs ??
      vfsMod?.default?.pdfMake?.vfs ??
      vfsMod?.default?.vfs ??
      (vfsMod && typeof vfsMod === "object" &&
       Object.keys(vfsMod).some((k) => k.endsWith(".ttf"))
        ? vfsMod
        : null);

    if (!vfs || !Object.keys(vfs).some((k) => k.endsWith(".ttf"))) {
      const diag =
        vfsMod && typeof vfsMod === "object"
          ? `keys: [${Object.keys(vfsMod).slice(0, 6).join(", ")}]`
          : `typeof: ${typeof vfsMod}`;
      throw new Error(
        `vfs_fonts.js: не найдены .ttf. ${diag}`
      );
    }

    printerInstance = new PdfPrinter({
      Roboto: {
        normal: Buffer.from(vfs["Roboto-Regular.ttf"], "base64"),
        bold: Buffer.from(vfs["Roboto-Medium.ttf"], "base64"),
        italics: Buffer.from(vfs["Roboto-Italic.ttf"], "base64"),
        bolditalics: Buffer.from(vfs["Roboto-MediumItalic.ttf"], "base64"),
      },
    });

    return printerInstance;
  } catch (e: any) {
    initError = e;
    throw e;
  }
}

// ─── Хелперы для таблиц ────────────────────────────────
function headerRow(labels: string[]) {
  return labels.map((t) => ({ text: t, style: "th" as const }));
}

// ─── Основной билдер ───────────────────────────────────
export async function buildAnalyticsPdf(
  data: AnalyticsSummary
): Promise<Buffer> {
  const printer = getPrinter();

  const metricsBody: any[][] = [headerRow(["Показатель", "Значение", "MoM"])];

  const addMetric = (label: string, value: string | number, mom?: number) => {
    metricsBody.push([
      label,
      { text: String(value), alignment: "right" },
      mom !== undefined
        ? {
            text: fmtPct(mom),
            color: pctColor(mom),
            bold: true,
            alignment: "right",
          }
        : { text: "—", color: "#CBD5E1", alignment: "right" },
    ]);
  };

  addMetric("План часов", data.totals.hours, data.totals.mom.hours);
  addMetric("Смен", data.totals.shifts, data.totals.mom.shifts);
  addMetric("План ФОТ", fmtMoney(data.totals.payroll), data.totals.mom.payroll);
  addMetric(
    "Факт ФОТ",
    fmtMoney(data.totals.actualPayroll),
    data.totals.mom.actualPayroll
  );
  addMetric(
    "Средняя цена смены",
    fmtMoney(data.totals.avgCost),
    data.totals.mom.avgCost
  );
  addMetric("Стоимость переработок", fmtMoney(data.totals.overtimeCost));
  addMetric("Фактические часы", data.planVsFact.actualHours);
  addMetric("План vs Факт", fmtPct(data.planVsFact.diffPercent));

  const weekdayBody: any[][] = [
    headerRow(["День", "Смен", "Часы", "ФОТ"]),
    ...data.byWeekday.map((d) => [
      {
        text: d.label,
        bold: d.weekday >= 5,
        color: d.weekday >= 5 ? "#7C3AED" : undefined,
      },
      { text: String(d.shifts), alignment: "right" },
      { text: String(d.plannedHours), alignment: "right" },
      { text: fmtMoney(d.payroll), alignment: "right" },
    ]),
  ];

  const positionBody: any[][] = [
    headerRow(["Должность", "Смен", "Часы", "ФОТ", "%"]),
    ...data.byPosition.map((p) => [
      p.position,
      { text: String(p.shifts), alignment: "right" },
      { text: String(p.plannedHours), alignment: "right" },
      { text: fmtMoney(p.payroll), alignment: "right" },
      { text: p.percent.toFixed(1) + "%", alignment: "right" },
    ]),
  ];

  const usersBody: any[][] = [
    headerRow([
      "Сотрудник",
      "Роль",
      "Смен",
      "План ч",
      "Факт ч",
      "План ФОТ",
      "Факт ФОТ",
      "Переработка",
    ]),
    ...data.users.map((u) => [
      u.name,
      ROLE_LABELS[u.role] ?? u.role,
      { text: String(u.shiftsCount), alignment: "right" },
      { text: String(u.plannedHours), alignment: "right" },
      { text: String(u.actualHours), alignment: "right" },
      { text: fmtMoney(u.plannedPayroll), alignment: "right" },
      { text: fmtMoney(u.actualPayroll), alignment: "right" },
      u.overtimeCost > 0
        ? {
            text: fmtMoney(u.overtimeCost),
            alignment: "right",
            color: "#D97706",
          }
        : { text: "—", color: "#CBD5E1", alignment: "right" },
    ]),
    [
      { text: "ИТОГО", bold: true },
      "",
      { text: String(data.totals.shifts), bold: true, alignment: "right" },
      { text: String(data.totals.hours), bold: true, alignment: "right" },
      {
        text: String(data.planVsFact.actualHours),
        bold: true,
        alignment: "right",
      },
      {
        text: fmtMoney(data.totals.payroll),
        bold: true,
        alignment: "right",
      },
      {
        text: fmtMoney(data.totals.actualPayroll),
        bold: true,
        alignment: "right",
      },
      {
        text: fmtMoney(data.totals.overtimeCost),
        bold: true,
        alignment: "right",
      },
    ],
  ];

  const docDefinition: any = {
    pageSize: "A4",
    pageMargins: [30, 30, 30, 40],
    defaultStyle: { font: "Roboto", fontSize: 9, color: "#0F172A" },
    footer: (cur: number, total: number) => ({
      columns: [
        {
          text: "Планировщик смен · Аналитика",
          color: "#94A3B8",
          fontSize: 8,
          margin: [30, 0, 0, 0],
        },
        {
          text: `${cur} / ${total}`,
          alignment: "right",
          color: "#94A3B8",
          fontSize: 8,
          margin: [0, 0, 30, 0],
        },
      ],
    }),
    content: [
      { text: "Аналитика", style: "h1" },
      {
        text: `Период: ${data.period.from} — ${data.period.to}`,
        color: "#475569",
        margin: [0, 0, 0, 2],
      },
      {
        text: `Сравнение с: ${data.prevPeriod.from} — ${data.prevPeriod.to}`,
        color: "#94A3B8",
        fontSize: 8,
        italics: true,
        margin: [0, 0, 0, 14],
      },

      { text: "Сводные показатели", style: "h2" },
      {
        table: {
          headerRows: 1,
          widths: ["*", "*", 70],
          body: metricsBody,
        },
        layout: "lightHorizontalLines",
        margin: [0, 0, 0, 14],
      },

      { text: "Нагрузка по дням недели", style: "h2" },
      {
        table: {
          headerRows: 1,
          widths: ["auto", "*", "*", "*"],
          body: weekdayBody,
        },
        layout: "lightHorizontalLines",
        margin: [0, 0, 0, 14],
      },

      { text: "ФОТ по должностям", style: "h2" },
      {
        table: {
          headerRows: 1,
          widths: ["*", "auto", "auto", "auto", "auto"],
          body: positionBody,
        },
        layout: "lightHorizontalLines",
      },

      { text: "Детализация по сотрудникам", style: "h2", pageBreak: "before" },
      {
        table: {
          headerRows: 1,
          widths: ["*", "auto", "auto", "auto", "auto", "auto", "auto", "auto"],
          body: usersBody,
        },
        layout: "lightHorizontalLines",
      },
    ],
    styles: {
      h1: { fontSize: 20, bold: true, margin: [0, 0, 0, 4] },
      h2: {
        fontSize: 12,
        bold: true,
        margin: [0, 4, 0, 8],
        color: "#1E293B",
      },
      th: {
        bold: true,
        color: "#FFFFFF",
        fillColor: "#2563EB",
        fontSize: 8,
      },
    },
  };

  const pdfDoc = printer.createPdfKitDocument(docDefinition);

  return new Promise<Buffer>((resolve, reject) => {
    const chunks: Buffer[] = [];
    pdfDoc.on("data", (chunk: Buffer) => chunks.push(chunk));
    pdfDoc.on("end", () => resolve(Buffer.concat(chunks)));
    pdfDoc.on("error", reject);
    pdfDoc.end();
  });
}

