import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { locationsService } from "./locations.service.js";

const createSchema = z.object({
  name: z.string().min(1).max(255),
  address: z.string().max(500).optional(),
  city: z.string().max(100).optional(),
  phone: z.string().max(20).optional(),
});

const updateSchema = createSchema.partial();
const setEmployeesSchema = z.object({ userIds: z.array(z.string().uuid()) });

export async function locationsRoutes(app: FastifyInstance) {
  app.addHook("preHandler", app.authenticate);

  app.get("/", async (req) => {
    const { orgId } = req.user!;
    return locationsService.list(orgId);
  });

  app.post("/", { preHandler: app.requireRole(["OWNER"]) }, async (req, reply) => {
    const parsed = createSchema.safeParse(req.body);
    if (!parsed.success) return reply.code(400).send({ error: parsed.error.flatten() });
    try {
      const { orgId } = req.user!;
      return await locationsService.create({ orgId, ...parsed.data });
    } catch (e: any) {
      if (e.message === "LOCATION_LIMIT_REACHED") {
        return reply.code(403).send({
          error: "Достигнут лимит точек на вашем тарифе",
          code: "LOCATION_LIMIT_REACHED",
        });
      }
      app.log.error(e);
      return reply.code(500).send({ error: "Ошибка создания точки" });
    }
  });

  app.patch<{ Params: { id: string } }>(
    "/:id",
    { preHandler: app.requireRole(["OWNER"]) },
    async (req, reply) => {
      const parsed = updateSchema.safeParse(req.body);
      if (!parsed.success) return reply.code(400).send({ error: parsed.error.flatten() });
      const { orgId } = req.user!;
      const updated = await locationsService.update({ id: req.params.id, orgId, ...parsed.data });
      if (!updated) return reply.code(404).send({ error: "Точка не найдена" });
      return updated;
    }
  );

  app.delete<{ Params: { id: string } }>(
    "/:id",
    { preHandler: app.requireRole(["OWNER"]) },
    async (req, reply) => {
      const { orgId } = req.user!;
      const archived = await locationsService.archive(req.params.id, orgId);
      if (!archived) return reply.code(404).send({ error: "Точка не найдена" });
      return { success: true };
    }
  );

  app.get<{ Params: { id: string } }>("/:id/employees", async (req, reply) => {
    try {
      const { orgId } = req.user!;
      return await locationsService.getEmployees(req.params.id, orgId);
    } catch (e: any) {
      if (e.message === "LOCATION_NOT_FOUND") return reply.code(404).send({ error: "Точка не найдена" });
      app.log.error(e);
      return reply.code(500).send({ error: "Ошибка" });
    }
  });

  app.put<{ Params: { id: string } }>(
    "/:id/employees",
    { preHandler: app.requireRole(["OWNER", "MANAGER"]) },
    async (req, reply) => {
      const parsed = setEmployeesSchema.safeParse(req.body);
      if (!parsed.success) return reply.code(400).send({ error: parsed.error.flatten() });
      try {
        const { orgId } = req.user!;
        return await locationsService.setEmployees(req.params.id, orgId, parsed.data.userIds);
      } catch (e: any) {
        if (e.message === "LOCATION_NOT_FOUND") return reply.code(404).send({ error: "Точка не найдена" });
        if (e.message === "INVALID_USER_IDS") return reply.code(400).send({ error: "Некорректные сотрудники" });
        app.log.error(e);
        return reply.code(500).send({ error: "Ошибка" });
      }
    }
  );
}

import { eq, and, inArray, sql } from "drizzle-orm";
import { db } from "../../../db/client.js";
import { locations, userLocations, users, organizations } from "../../../db/schema.js";

export const locationsService = {
  async list(orgId: string) {
    return db
      .select()
      .from(locations)
      .where(and(eq(locations.orgId, orgId), eq(locations.isArchived, false)))
      .orderBy(locations.createdAt);
  },

  async create(input: {
    orgId: string;
    name: string;
    address?: string;
    city?: string;
    phone?: string;
  }) {
    const [org] = await db
      .select({ maxLocations: organizations.maxLocations })
      .from(organizations)
      .where(eq(organizations.id, input.orgId));

    const [countRow] = await db
      .select({ count: sql<number>`count(*)::int` })
      .from(locations)
      .where(and(eq(locations.orgId, input.orgId), eq(locations.isArchived, false)));

    if (countRow.count >= (org?.maxLocations ?? 1)) {
      throw new Error("LOCATION_LIMIT_REACHED");
    }

    const [created] = await db
      .insert(locations)
      .values({
        orgId: input.orgId,
        name: input.name,
        address: input.address,
        city: input.city,
        phone: input.phone,
      })
      .returning();
    return created;
  },

  async update(input: {
    id: string;
    orgId: string;
    name?: string;
    address?: string | null;
    city?: string | null;
    phone?: string | null;
  }) {
    const [updated] = await db
      .update(locations)
      .set({
        ...(input.name !== undefined && { name: input.name }),
        ...(input.address !== undefined && { address: input.address }),
        ...(input.city !== undefined && { city: input.city }),
        ...(input.phone !== undefined && { phone: input.phone }),
      })
      .where(and(eq(locations.id, input.id), eq(locations.orgId, input.orgId)))
      .returning();
    return updated;
  },

  async archive(id: string, orgId: string) {
    const [updated] = await db
      .update(locations)
      .set({ isArchived: true })
      .where(and(eq(locations.id, id), eq(locations.orgId, orgId)))
      .returning();
    return updated;
  },

  async getEmployees(locationId: string, orgId: string) {
    const [loc] = await db
      .select()
      .from(locations)
      .where(and(eq(locations.id, locationId), eq(locations.orgId, orgId)));
    if (!loc) throw new Error("LOCATION_NOT_FOUND");

    return db
      .select({
        id: users.id,
        name: users.name,
        email: users.email,
        role: users.role,
        position: users.position,
      })
      .from(userLocations)
      .innerJoin(users, eq(users.id, userLocations.userId))
      .where(eq(userLocations.locationId, locationId));
  },

  async setEmployees(locationId: string, orgId: string, userIds: string[]) {
    const [loc] = await db
      .select()
      .from(locations)
      .where(and(eq(locations.id, locationId), eq(locations.orgId, orgId)));
    if (!loc) throw new Error("LOCATION_NOT_FOUND");

    if (userIds.length > 0) {
      const valid = await db
        .select({ id: users.id })
        .from(users)
        .where(and(eq(users.orgId, orgId), inArray(users.id, userIds)));
      if (valid.length !== userIds.length) throw new Error("INVALID_USER_IDS");
    }

    await db.delete(userLocations).where(eq(userLocations.locationId, locationId));
    if (userIds.length > 0) {
      await db
        .insert(userLocations)
        .values(userIds.map((userId) => ({ userId, locationId })));
    }
    return { success: true, count: userIds.length };
  },
};

