                                     relatedType: string,
                                     status: "APPROVED" | "REJECTED",
                                     resolverName: string,
                                     detail: string
                                   ) {
                                     const title = status === "APPROVED" ? "Запрос одобрен" : "Запрос отклонён";
                                     const message = `${resolverName} ${status === "APPROVED" ? "одобрил(а)" : "отклонил(а)"}: ${detail}`;
                                     await db
                                       .update(userNotifications)
                                       .set({
                                         requiresAction: false,
                                         title,
                                         message,
                                         acknowledgedAt: null,
                                       })
                                       .where(
                                         and(
                                           eq(userNotifications.relatedId, relatedId),
                                           eq(userNotifications.relatedType, relatedType),
                                           eq(userNotifications.requiresAction, true)
                                         )
                                       );
                                     return { success: true };
                                   },

                                   async dismissActionable(relatedId: string, relatedType?: string) {
               const cond = relatedType
                 ? and(
                     eq(userNotifications.relatedId, relatedId),
                     eq(userNotifications.relatedType, relatedType),
                     eq(userNotifications.requiresAction, true),
                     isNull(userNotifications.acknowledgedAt)
                   )
                 : and(
                     eq(userNotifications.relatedId, relatedId),
                     eq(userNotifications.requiresAction, true),
                     isNull(userNotifications.acknowledgedAt)
                   );
               await db.delete(userNotifications).where(cond);
               return { success: true };
             },
};

