// superpatch.mjs
import fs from "node:fs";
import path from "node:path";

const ROOT = process.cwd();
const filePath = path.join(ROOT, "frontend/src/pages/WeekDetailPage.tsx");

if (!fs.existsSync(filePath)) {
  console.log("❌ Файл WeekDetailPage.tsx не найден!");
  process.exit(1);
}

let content = fs.readFileSync(filePath, "utf-8");
const hadCRLF = content.includes("\r\n");
let normalized = hadCRLF ? content.replace(/\r\n/g, "\n") : content;

// Ищем блок с текстом "Ждёт согласования" внутри исходящих запросов
const searchStr = `                      <div className="mt-1.5 flex items-center gap-1 text-[10px] font-medium text-slate-600 bg-slate-100 rounded px-1.5 py-0.5 leading-tight">
                        <Clock className="w-3 h-3 shrink-0" />
                        <span>Ждёт согласования</span>
                      </div>`;

const replaceStr = `                      <div className="mt-1.5 flex items-center gap-1 text-[10px] font-medium text-slate-600 bg-slate-100 rounded px-1.5 py-0.5 leading-tight">
                        <Clock className="w-3 h-3 shrink-0" />
                        <span>Ждёт согласования</span>
                      </div>

                      {/* Красивая всплывающая подсказка */}
                      <div className="absolute bottom-[calc(100%+8px)] left-1/2 -translate-x-1/2 w-64 bg-slate-800 text-white p-3 rounded-xl shadow-2xl opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all z-[60] pointer-events-none text-center leading-snug">
                        <div className="font-bold text-sm mb-1 text-white">{getUserInfo(r.newUserId).name}</div>
                        <div className="text-slate-300 text-xs">должен согласовать изменение смены в своём профиле</div>
                        <div className="absolute top-full left-1/2 -translate-x-1/2 border-[6px] border-transparent border-t-slate-800" />
                      </div>`;

if (normalized.includes(searchStr)) {
  // Проверяем, нет ли уже визуального тултипа рядом
  if (!normalized.includes("absolute bottom-[calc(100%+8px)]")) {
    normalized = normalized.replace(searchStr, replaceStr);
    fs.writeFileSync(filePath, hadCRLF ? normalized.replace(/\n/g, "\r\n") : normalized, "utf-8");
    console.log("✅ [WeekDetailPage] Визуальная подсказка успешно добавлена!");
  } else {
    console.log("⏭  [WeekDetailPage] Визуальная подсказка уже присутствует в этом блоке.");
  }
} else {
  // Если отступы чуть другие, используем Regex
  const regex = /(<div className="mt-1\.5 flex items-center gap-1 text-\[10px\] font-medium text-slate-600 bg-slate-100 rounded px-1\.5 py-0\.5 leading-tight">[\s\S]*?Ждёт согласования[\s\S]*?<\/div>)/;
  
  if (regex.test(normalized) && !normalized.includes("absolute bottom-[calc(100%+8px)]")) {
    normalized = normalized.replace(regex, "$1\n\n" + replaceStr.split('\n').slice(6).join('\n'));
    fs.writeFileSync(filePath, hadCRLF ? normalized.replace(/\n/g, "\r\n") : normalized, "utf-8");
    console.log("✅ [WeekDetailPage] Визуальная подсказка добавлена через Regex (fallback).");
  } else {
    console.log("❌ [WeekDetailPage] Не удалось найти блок 'Ждёт согласования'. Возможно, он уже пропатчен.");
  }
}
